1: @page "/"
2: @rendermode InteractiveServer
3: @using Gram.Blazor.Shared
4: 
5: <PageTitle>Gram</PageTitle>
6: 
7: <div class="workspace">
8:     <aside class="conversation-rail">
9:         <div class="rail-heading"><span>CONVERSATIONS</span><button class="icon-button" @onclick="NewConversation" title="New conversation">+</button></div>
10:         <button class="new-chat" @onclick="NewConversation">＋ New conversation</button>
11:         <div class="conversation-list">
12:             @foreach (var chat in conversations)
13:             {
14:                 <button class="conversation @(chat.Id == activeId ? "active" : "")" @onclick="() => SelectConversation(chat.Id)">
15:                     <span class="conversation-title">@chat.Title</span><small>@chat.Updated.ToLocalTime().ToString("MMM d")</small>
16:                 </button>
17:             }
18:         </div>
19:         <a class="rail-settings" href="/settings">⚙ Settings</a>
20:     </aside>
21: 
22:     <section class="chat-panel">
23:         <div class="chat-header"><div><span class="eyebrow">LOCAL ASSISTANT</span><h1>@Active.Title</h1></div><span class="model-pill">@modelName</span></div>
24:         <div class="messages">
25:             @if (Active.Messages.Count == 0)
26:             {
27:                 <div class="welcome"><div class="signal">◈</div><h2>What can I help with?</h2><p>Ask about your files, schedule, weather, or everyday tasks.</p></div>
28:             }
29:             @foreach (var message in Active.Messages)
30:             {
31:                 <div class="message @(message.Role == "user" ? "user-message" : "assistant-message")"><span class="message-role">@(message.Role == "user" ? "YOU" : "GRAM")</span><p>@message.Text</p></div>
32:             }
33:         </div>
34:         <div class="composer"><textarea @bind="draft" @bind:event="oninput" placeholder="Talk to Gram or type a request…" @onkeydown="HandleKey"></textarea><div class="composer-footer"><span>Enter to send · Shift+Enter for a new line</span><button class="send-button" @onclick="Send">Send ↑</button></div></div>
35:     </section>
36: </div>
37: 
38: @code {
39:     private readonly List<Conversation> conversations = new() { new("today", "Today", DateTimeOffset.UtcNow) };
40:     private string activeId = "today";
41:     private string draft = "";
42:     private string modelName = "Local assistant";
43:     private Conversation Active => conversations.First(x => x.Id == activeId);
44: 
45:     private void NewConversation()
46:     {
47:         var id = Guid.NewGuid().ToString("N")[..8];
48:         conversations.Insert(0, new Conversation(id, "New conversation", DateTimeOffset.UtcNow));
49:         activeId = id;
50:     }
51: 
52:     private void SelectConversation(string id) => activeId = id;
53: 
54:     private void HandleKey(KeyboardEventArgs e)
55:     {
56:         if (e.Key == "Enter" && !e.ShiftKey) Send();
57:     }
58: 
59:     private void Send()
60:     {
61:         if (string.IsNullOrWhiteSpace(draft)) return;
62:         Active.Messages.Add(new Message("user", draft.Trim()));
63:         Active.Messages.Add(new Message("assistant", "The local core is ready. Connect the assistant service to start answering here."));
64:         Active.Title = Active.Messages.First(x => x.Role == "user").Text[..Math.Min(32, Active.Messages.First(x => x.Role == "user").Text.Length)];
65:         Active.Updated = DateTimeOffset.UtcNow;
66:         draft = "";
67:     }
68: }
