args.CodeContent:
:root {
  --bg-body: #0c0f14;
  --bg-panel: #131720;
  --bg-panel-subtle: #181d28;
  --bg-hover: #1e2433;
  --bg-active: #242c3d;
  --border-color: #222938;
  --border-focus: #3b82f6;

  --text-primary: #e5e7eb;
  --text-secondary: #9ca3af;
  --text-muted: #64748b;

  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --accent-light: rgba(37, 99, 235, 0.12);
  --success: #10b981;
  --success-bg: rgba(16, 185, 129, 0.1);
  --warning: #f59e0b;
  --danger: #ef4444;
  --danger-hover: #dc2626;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;

  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.25);
  --shadow-md: 0 4px 12px 0 rgba(0, 0, 0, 0.35);
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  background-color: var(--bg-body);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

/* App Shell */
.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Top Navbar */
.topbar {
  height: 52px;
  background-color: var(--bg-panel);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  z-index: 10;
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.05em;
}

.brand-badge {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  background: var(--bg-hover);
  color: var(--text-secondary);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  font-weight: 600;
}

.topbar-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: 12px;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 13px;
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  transition: all 0.15s ease;
}

.nav-link:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.nav-link.active {
  color: var(--text-primary);
  background: var(--bg-active);
  font-weight: 500;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.status-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  padding: 4px 10px;
  border-radius: 9999px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--success);
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.4);
}

/* Page Frame */
.page-frame {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 16px;
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
}

/* Main Workspace Layout */
.workspace {
  flex: 1;
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr);
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  height: calc(100vh - 84px);
}

/* Sidebar / Rail */
.conversation-rail {
  border-right: 1px solid var(--border-color);
  background: var(--bg-panel-subtle);
  display: flex;
  flex-direction: column;
  padding: 14px;
  overflow: hidden;
}

.rail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.rail-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.btn-new-chat {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  margin-bottom: 12px;
  transition: background 0.15s ease;
}

.btn-new-chat:hover {
  background: var(--accent-hover);
}

.conversation-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-right: 2px;
}

.conversation-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  padding: 8px 10px;
  text-align: left;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
  group: relative;
}

.conversation-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.conversation-item.active {
  background: var(--bg-active);
  color: var(--text-primary);
  border-color: var(--border-color);
}

.conv-meta {
  min-width: 0;
  flex: 1;
}

.conv-title {
  display: block;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.conv-time {
  display: block;
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 1px;
}

.conv-delete {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  opacity: 0;
  transition: opacity 0.15s ease, color 0.15s ease;
}

.conversation-item:hover .conv-delete {
  opacity: 1;
}

.conv-delete:hover {
  color: var(--danger);
  background: rgba(239, 68, 68, 0.1);
}

.rail-footer {
  padding-top: 12px;
  border-top: 1px solid var(--border-color);
  margin-top: auto;
}

/* Chat Main Panel */
.chat-panel {
  display: flex;
  flex-direction: column;
  background: var(--bg-panel);
  min-width: 0;
  height: 100%;
}

.chat-header {
  height: 52px;
  border-bottom: 1px solid var(--border-color);
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel);
}

.chat-header-info {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.chat-header h1 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.badge-tag {
  font-size: 11px;
  background: var(--bg-hover);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
}

.chat-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-subtle {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 12px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-subtle:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* Message Thread */
.messages-container {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Empty State / Welcome */
.harness-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: auto;
  text-align: center;
  max-width: 520px;
  padding: 32px 16px;
}

.empty-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin-bottom: 16px;
}

.harness-empty-state h2 {
  font-size: 17px;
  font-weight: 600;
  margin: 0 0 6px 0;
}

.harness-empty-state p {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0 0 20px 0;
}

.prompt-suggestions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.prompt-chip {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  text-align: left;
  font-size: 12px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.prompt-chip:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: #3b4252;
}

.prompt-chip span.arrow {
  color: var(--text-muted);
}

/* Message Entries */
.message-entry {
  display: flex;
  flex-direction: column;
  max-width: 800px;
  width: 100%;
  margin: 0 auto;
}

.message-entry.user {
  align-items: flex-end;
}

.message-entry.assistant {
  align-items: flex-start;
}

.message-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
}

.message-body {
  padding: 10px 14px;
  border-radius: var(--radius-md);
  font-size: 13.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
}

.message-entry.user .message-body {
  background: var(--accent);
  color: #ffffff;
  border-bottom-right-radius: 2px;
}

.message-entry.assistant .message-body {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  border-bottom-left-radius: 2px;
}

/* Composer */
.composer-wrapper {
  padding: 14px 20px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.composer-box {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  transition: border-color 0.15s ease;
  max-width: 800px;
  margin: 0 auto;
}

.composer-box:focus-within {
  border-color: var(--border-focus);
}

.composer-textarea {
  width: 100%;
  min-height: 52px;
  max-height: 180px;
  background: transparent;
  border: none;
  outline: none;
  resize: vertical;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13.5px;
  line-height: 1.5;
}

.composer-textarea::placeholder {
  color: var(--text-muted);
}

.composer-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 6px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.composer-hint {
  font-size: 11px;
  color: var(--text-muted);
}

.btn-send {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease;
}

.btn-send:hover {
  background: var(--accent-hover);
}

.btn-send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Settings Layout */
.settings-layout {
  flex: 1;
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
