        <div class="rail-heading"><span>CONVERSATIONS</span><button class="icon-button" @onclick="NewConversation" title="New conversation">+</button></div>
        <button class="new-chat" @onclick="NewConversation">＋ New conversation</button>
        <div class="conversation-list">
            @foreach (var chat in conversations)
            {
                <button class="conversation @(chat.Id == activeId ? "active" : "")" @onclick="() => SelectConversation(chat.Id)">
                    <span class="conversation-title">@chat.Title</span><small>@chat.Updated.ToLocalTime().ToString("MMM d")</small>
                </button>
            }
        </div>
        <a class="rail-settings" href="/settings">⚙ Settings</a>
    </aside>

    <section class="chat-panel">
        <div class="chat-header"><div><span class="eyebrow">LOCAL ASSISTANT</span><h1>@Active.Title</h1></div><span class="model-pill">@modelName</span></div>
        <div class="messages">
            @if (Active.Messages.Count == 0)
            {
                <div class="welcome"><div class="signal">◈</div><h2>What can I help with?</h2><p>Ask about your files, schedule, weather, or everyday tasks.</p></div>
            }
            @foreach (var message in Active.Messages)
            {
                <div class="message @(message.Role == "user" ? "user-message" : "assistant-message")"><span class="message-role">@(message.Role == "user" ? "YOU" : "GRAM")</span><p>@message.Text</p></div>
            }
        </div>
        <div class="composer"><textarea @bind="draft" @bind:event="oninput" placeholder="Talk to Gram or type a request…" @onkeydown="HandleKey"></textarea><div class="composer-footer"><span>Enter to send · Shift+Enter for a new line</span><button class="send-button" @onclick="Send">Send ↑</button></div></div>
    </section>
</div>

@code {
    private readonly List<Conversation> conversations = new() { new("today", "Today", DateTimeOffset.UtcNow) };
    private string activeId = "today";
    private string draft = "";
    private string modelName = "Local assistant";
    private Conversation Active => conversations.First(x => x.Id == activeId);

    private void NewConversation()
    {
        var id = Guid.NewGuid().ToString("N")[..8];
        conversations.Insert(0, new Conversation(id, "New conversation", DateTimeOffset.UtcNow));
        activeId = id;
    }

    private void SelectConversation(string id) => activeId = id;

    private void HandleKey(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey) Send();
    }

    private void Send()
    {
        if (string.IsNullOrWhiteSpace(draft)) return;
        Active.Messages.Add(new Message("user", draft.Trim()));
        Active.Messages.Add(new Message("assistant", "The local core is ready. Connect the assistant service to start answering here."));
        Active.Title = Active.Messages.First(x => x.Role == "user").Text[..Math.Min(32, Active.Messages.First(x => x.Role == "user").Text.Length)];
        Active.Updated = DateTimeOffset.UtcNow;
        draft = "";
    }
}

