args.TargetContent:
@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings · Gram</PageTitle>
<div class="settings-layout">
    <aside class="settings-sidebar">
        <a class="back-link" href="/">← Conversations</a>
        <h1>Settings</h1>
        <input class="settings-search" @bind="search" @bind:event="oninput" placeholder="Search settings" />
        <nav>
            @foreach (var item in VisibleGroups)
            {
                <button class="setting-nav @(activeGroup == item ? "selected" : "")" @onclick="() => activeGroup = item">@Icon(item) @item</button>
            }
        </nav>
    </aside>
    <section class="settings-content">
        <span class="eyebrow">CONFIGURATION</span><h2>@activeGroup</h2>
        @if (activeGroup == "General")
        {
            <div class="setting-card"><label>Assistant name</label><input value="Gram" /><small>Shown in the conversation header and spoken introduction.</small></div>
            <div class="setting-card"><label>RAM budget</label><div class="static-value">2 GB maximum target</div><small>The frontend stays model-free. Ollama and other model processes are managed separately.</small></div>
        }
        else if (activeGroup == "Models")
        {
            <div class="setting-card"><label>Local assistant</label><div class="static-value">Ollama · qwen3.5:9b</div><small>Used for quick local tasks. Coding requests can route to OpenRouter.</small></div>
            <div class="setting-card"><label>OpenRouter</label><div class="static-value">Configured in Gram core</div><small>Only allowlisted models are permitted.</small></div>
        }
        else if (activeGroup == "Audio")
        {
            <div class="setting-card"><label>Input and output devices</label><div class="static-value">Managed by Gram core</div><small>Use the audio test to verify the selected microphone and speaker.</small><button class="secondary">Open audio test</button></div>
        }
        else if (activeGroup == "MCP")
        {
            <div class="setting-card"><label>Connected servers</label><div class="static-value">No servers shown yet</div><small>Add approved MCP servers through the Gram core. Tools remain allowlisted and confirmable.</small><button class="secondary">Add MCP server</button></div>
        }
        else
        {
            <div class="setting-card"><label>Latest logs</label><p>Diagnostic logs are kept locally by Gram.</p><a class="log-link" href="/api/logs/gram.log" target="_blank">Open latest log ↗</a></div>
        }
    </section>
</div>

@code {
    private string search = "";
    private string activeGroup = "General";
    private readonly string[] groups = ["General", "Models", "Audio", "MCP", "Logs"];
    private IEnumerable<string> VisibleGroups => groups.Where(x => string.IsNullOrWhiteSpace(search) || x.Contains(search, StringComparison.OrdinalIgnoreCase));
    private static string Icon(string group) => group switch { "General" => "◌", "Models" => "◇", "Audio" => "◒", "MCP" => "⌘", _ => "▤" };
}

