    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            Send();
        }
    }

    private void Send()
    {
        if (string.IsNullOrWhiteSpace(draft)) return;
        var text = draft.Trim();
        draft = "";

        Active.Messages.Add(new Message("user", text));

        if (Active.Messages.Count(m => m.Role == "user") == 1)
        {
            Active.Title = text.Length > 28 ? text[..28] + "…" : text;
        }

        Active.Messages.Add(new Message("assistant", "The local core is ready. Connect the assistant service to stream live model responses."));
        Active.Updated = DateTimeOffset.UtcNow;
    }
}

