/* Attachment Tray */
.attachment-tray {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  max-width: 800px;
  margin: 0 auto 8px auto;
}

.attachment-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-size: 12px;
  color: var(--text-primary);
}

.attachment-name {
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.btn-remove-attachment {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0 2px;
  font-size: 11px;
  line-height: 1;
}

.btn-remove-attachment:hover {
  color: var(--danger);
}

/* Audio Visualizer Banner */
.voice-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 800px;
  margin: 0 auto 10px auto;
  background: var(--bg-panel-subtle);
  border: 1px solid rgba(168, 85, 247, 0.3);
  border-radius: var(--radius-md);
  padding: 8px 14px;
}

.voice-banner.user-voice {
  border-color: rgba(192, 132, 252, 0.4);
}

.voice-banner.assistant-voice {
  border-color: rgba(147, 51, 234, 0.5);
  background: rgba(147, 51, 234, 0.08);
}

.voice-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.visualizer-bars {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 20px;
}

.visualizer-bars .v-bar {
  width: 3px;
  height: 4px;
  background: var(--accent);
  border-radius: 2px;
  animation: wave 1.2s ease-in-out infinite alternate;
}

.voice-banner.user-voice .visualizer-bars .v-bar {
  background: #c084fc;
}

.voice-banner.assistant-voice .visualizer-bars .v-bar {
  background: #a855f7;
}

.visualizer-bars .v-bar:nth-child(1) { animation-delay: 0.1s; height: 6px; }
