@page "/"
@rendermode InteractiveServer
@using Gram.Blazor.Shared

<PageTitle>Gram</PageTitle>

<div class="workspace">
    <aside class="conversation-rail">
        <div class="rail-header">
            <span class="rail-title">Chats</span>
        </div>

        <button class="btn-new-chat" @onclick="NewConversation">
            New chat
        </button>

        <div class="conversation-list">
            @foreach (var chat in conversations)
            {
                <div class="conversation-item @(chat.Id == activeId ? "active" : "")" @onclick="() => SelectConversation(chat.Id)">
                    <div class="conv-meta">
                        <span class="conv-title">@chat.Title</span>
                        <span class="conv-time">@chat.Updated.ToLocalTime().ToString("h:mm tt · MMM d")</span>
                    </div>
                    @if (conversations.Count > 1)
                    {
                        <button class="conv-delete" title="Delete" @onclick:stopPropagation="true" @onclick="() => DeleteConversation(chat.Id)">✕</button>
                    }
                </div>
            }
        </div>
    </aside>

    <section class="chat-panel">
        <div class="chat-header">
            <div class="chat-header-info">
                <h1>@Active.Title</h1>
            </div>
            <div class="chat-actions">
                @if (Active.Messages.Count > 0)
                {
                    <button class="btn-subtle" @onclick="ClearCurrentChat" title="Clear chat">Clear</button>
                }
            </div>
        </div>

        <div class="messages-container">
            @if (Active.Messages.Count == 0)
            {
                <div class="harness-empty-state">
                    <h2>How can I help?</h2>
                    <p>Send a message to get started.</p>
                </div>
            }
            else
            {
                @foreach (var message in Active.Messages)
                {
                    <div class="message-entry @(message.Role == "user" ? "user" : "assistant")">
                        <div class="message-header">
                            <span>@(message.Role == "user" ? "You" : "Gram")</span>
                        </div>
                        <div class="message-body">@message.Text</div>
                    </div>
                }
            }
        </div>

        <div class="composer-wrapper">
            <div class="composer-box">
                <textarea class="composer-textarea"
                          @bind="draft"
                          @bind:event="oninput"
                          placeholder="Message Gram..."
                          @onkeydown="HandleKey"></textarea>

                <div class="composer-footer">
                    <span class="composer-hint">Enter to send, Shift+Enter for new line</span>
                    <button class="btn-send" @onclick="Send" disabled="@(string.IsNullOrWhiteSpace(draft))">
                        Send
                    </button>
                </div>
            </div>
        </div>
    </section>
</div>

@code {
    private readonly List<Conversation> conversations = new() { new("default", "New chat", DateTimeOffset.UtcNow) };
    private string activeId = "default";
    private string draft = "";
    private Conversation Active => conversations.FirstOrDefault(x => x.Id == activeId) ?? conversations.First();

    private void NewConversation()
    {
        var id = Guid.NewGuid().ToString("N")[..8];
        conversations.Insert(0, new Conversation(id, "New chat", DateTimeOffset.UtcNow));
        activeId = id;
    }

    private void SelectConversation(string id) => activeId = id;

    private void DeleteConversation(string id)
    {
        if (conversations.Count <= 1) return;
        var index = conversations.FindIndex(x => x.Id == id);
        if (index >= 0)
        {
            conversations.RemoveAt(index);
            if (activeId == id)
            {
                activeId = conversations[Math.Min(index, conversations.Count - 1)].Id;
            }
        }
    }

    private void ClearCurrentChat()
    {
        Active.Messages.Clear();
        Active.Title = "New chat";
        Active.Updated = DateTimeOffset.UtcNow;
    }

    private void HandleKey(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            Send();
        }
    }

    private void Send()
    {
        if (string.IsNullOrWhiteSpace(draft)) return;
        var text = draft.Trim();
        draft = "";

        Active.Messages.Add(new Message("user", text));

        if (Active.Messages.Count(m => m.Role == "user") == 1)
        {
            Active.Title = text.Length > 28 ? text[..28] + "…" : text;
        }

        Active.Messages.Add(new Message("assistant", "I'm connected and ready."));
        Active.Updated = DateTimeOffset.UtcNow;
    }
}

