/* Audio Visualizer Banner */
.voice-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 800px;
  margin: 0 auto 10px auto;
  background: var(--bg-panel-subtle);
  border: 1px solid rgba(168, 85, 247, 0.3);
  border-radius: var(--radius-md);
  padding: 8px 14px;
  transition: all 0.2s ease;
}

.voice-banner.user-voice {
  border-color: rgba(192, 132, 252, 0.4);
}

.voice-banner.assistant-voice {
  border-color: rgba(147, 51, 234, 0.5);
  background: rgba(147, 51, 234, 0.08);
}

.voice-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.visualizer-bars {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 26px;
}

.visualizer-bars .v-bar {
  width: 3px;
  height: 3px;
  background: #c084fc;
  border-radius: 2px;
  opacity: 0.35;
  transition: height 0.06s ease-out, opacity 0.06s ease-out;
}

.voice-banner.assistant-voice .visualizer-bars .v-bar {
  background: #a855f7;
  animation: assistantWave 1.1s ease-in-out infinite alternate;
}

.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(1) { animation-delay: 0.1s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(2) { animation-delay: 0.3s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(3) { animation-delay: 0.15s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(4) { animation-delay: 0.4s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(5) { animation-delay: 0.25s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(6) { animation-delay: 0.5s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(7) { animation-delay: 0.35s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(8) { animation-delay: 0.05s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(9) { animation-delay: 0.45s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(10) { animation-delay: 0.2s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(11) { animation-delay: 0.38s; }
.voice-banner.assistant-voice .visualizer-bars .v-bar:nth-child(12) { animation-delay: 0.18s; }

@keyframes assistantWave {
  0% {
    height: 4px;
    opacity: 0.4;
  }
  50% {
    height: 20px;
    opacity: 0.95;
  }
  100% {
    height: 8px;
    opacity: 0.6;
  }
}

.voice-label {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-primary);
}

.btn-stop-voice {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11px;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-stop-voice:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* Composer Dock */
.composer-wrapper {
  padding: 12px 24px 18px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-panel);
}

.composer-box {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: 22px;
  padding: 6px 10px 6px 8px;
  transition: all 0.15s ease;
  max-width: 800px;
  margin: 0 auto;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.composer-box:focus-within {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px rgba(168, 85, 247, 0.18), 0 4px 16px rgba(0, 0, 0, 0.4);
}

.composer-inner {
  display: flex;
  align-items: flex-end;
  gap: 6px;
}

.composer-textarea {
  flex: 1;
  min-height: 26px;
  max-height: 160px;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13.5px;
  line-height: 1.45;
  padding: 6px 6px;
}

