@page "/"
@rendermode InteractiveServer
@using Gram.Blazor.Shared
@using Microsoft.AspNetCore.Components.Forms
@inject IJSRuntime JSRuntime
@implements IAsyncDisposable

<PageTitle>Gram</PageTitle>

<div class="workspace">
    <aside class="conversation-rail">
        <div class="rail-header">
            <span class="rail-title">Chats</span>
        </div>

        <button class="btn-new-chat" @onclick="NewConversation">
            New chat
        </button>

        <div class="conversation-list">
            @foreach (var chat in conversations)
            {
                <div class="conversation-item @(chat.Id == activeId ? "active" : "")" @onclick="() => SelectConversation(chat.Id)">
                    <div class="conv-meta">
                        <span class="conv-title">@chat.Title</span>
                        <span class="conv-time">@chat.Updated.ToLocalTime().ToString("h:mm tt · MMM d")</span>
                    </div>
                    @if (conversations.Count > 1)
                    {
                        <button class="conv-delete" title="Delete" @onclick:stopPropagation="true" @onclick="() => DeleteConversation(chat.Id)">✕</button>
                    }
                </div>
            }
        </div>
    </aside>

    <section class="chat-panel">
        <div class="chat-header">
            <div class="chat-header-info">
                <h1>@Active.Title</h1>
            </div>
            <div class="chat-actions">
                @if (Active.Messages.Count > 0)
                {
                    <button class="btn-subtle" @onclick="ClearCurrentChat" title="Clear chat">Clear</button>
                }
            </div>
        </div>

        <div class="messages-container">
            @if (Active.Messages.Count == 0)
            {
                <div class="harness-empty-state">
                    <h2>How can I help?</h2>
                    <p>Type a message or tap the microphone to speak.</p>
                </div>
            }
            else
            {
                @foreach (var message in Active.Messages)
                {
                    <div class="message-entry @(message.Role == "user" ? "user" : "assistant")">
                        <div class="message-header">
                            <span>@(message.Role == "user" ? "You" : "Gram")</span>
                        </div>
                        <div class="message-body">@message.Text</div>
                    </div>
                }
            }
        </div>

        <div class="composer-wrapper">
            @if (attachedFiles.Count > 0)
            {
                <div class="attachment-tray">
                    @foreach (var file in attachedFiles)
                    {
                        <div class="attachment-pill">
                            <span class="attachment-name">📎 @file</span>
                            <button class="btn-remove-attachment" @onclick="() => RemoveFile(file)" title="Remove file">✕</button>
                        </div>
                    }
                </div>
            }

            @if (voiceState != VoiceState.Idle)
            {
                <div class="voice-banner @(voiceState == VoiceState.UserSpeaking ? "user-voice" : "assistant-voice")">
                    <div class="voice-info">
                        <div class="visualizer-bars" id="visualizerBars">
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                            <span class="v-bar"></span>
                        </div>
                        <span class="voice-label">@(voiceState == VoiceState.UserSpeaking ? "Listening to your voice..." : "Gram is speaking...")</span>
                    </div>
                    <button class="btn-stop-voice" @onclick="StopVoice">Stop</button>
                </div>
            }

            <div class="composer-box">
                <InputFile id="fileInput" OnChange="HandleFileSelected" style="display: none;" multiple />

                <div class="composer-inner">
                    <div class="composer-actions-left">
                        <label for="fileInput" class="btn-composer-icon" title="Attach files">
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <line x1="12" y1="5" x2="12" y2="19"></line>
                                <line x1="5" y1="12" x2="19" y2="12"></line>
                            </svg>
                        </label>
                    </div>

                    <textarea @ref="textareaRef"
                              class="composer-textarea"
                              @bind="draft"
                              @bind:event="oninput"
                              placeholder="@(voiceState == VoiceState.UserSpeaking ? "Listening..." : "Message Gram...")"
                              @onkeydown="HandleKey"></textarea>

                    <div class="composer-actions-right">
                        <button class="btn-composer-icon voice-btn @(voiceState != VoiceState.Idle ? "active" : "")"
                                @onclick="ToggleVoice"
                                title="@(voiceState == VoiceState.Idle ? "Voice input" : "Stop voice")">
                            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"></path>
                                <path d="M19 10v2a7 7 0 0 1-14 0v-2"></path>
                                <line x1="12" y1="19" x2="12" y2="23"></line>
                                <line x1="8" y1="23" x2="16" y2="23"></line>
                            </svg>
                        </button>

                        <button class="btn-composer-send"
                                @onclick="Send"
                                disabled="@(string.IsNullOrWhiteSpace(draft) && attachedFiles.Count == 0 && voiceState == VoiceState.Idle)"
                                title="Send">
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <line x1="22" y1="2" x2="11" y2="13"></line>
                                <polygon points="22 2 15 22 11 13 2 9 22 2"></polygon>
                            </svg>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </section>
</div>

@code {
    private enum VoiceState { Idle, UserSpeaking, GramSpeaking }

    private readonly List<Conversation> conversations = new() { new("default", "New chat", DateTimeOffset.UtcNow) };
    private string activeId = "default";
    private string draft = "";
    private readonly List<string> attachedFiles = new();
    private VoiceState voiceState = VoiceState.Idle;
    private DotNetObjectReference<Home>? dotNetHelper;
    private ElementReference textareaRef;
    private CancellationTokenSource? voiceCts;

    private Conversation Active => conversations.FirstOrDefault(x => x.Id == activeId) ?? conversations.First();

    protected override void OnInitialized()
    {
        dotNetHelper = DotNetObjectReference.Create(this);
    }

    private void NewConversation()
    {
        var id = Guid.NewGuid().ToString("N")[..8];
        conversations.Insert(0, new Conversation(id, "New chat", DateTimeOffset.UtcNow));
        activeId = id;
    }

    private void SelectConversation(string id) => activeId = id;

    private void DeleteConversation(string id)
    {
        if (conversations.Count <= 1) return;
        var index = conversations.FindIndex(x => x.Id == id);
        if (index >= 0)
        {
            conversations.RemoveAt(index);
            if (activeId == id)
            {
                activeId = conversations[Math.Min(index, conversations.Count - 1)].Id;
            }
        }
    }

    private async Task ClearCurrentChat()
    {
        Active.Messages.Clear();
        Active.Title = "New chat";
        Active.Updated = DateTimeOffset.UtcNow;
        attachedFiles.Clear();
        await StopVoice();
    }

    private void HandleFileSelected(InputFileChangeEventArgs e)
    {
        foreach (var file in e.GetMultipleFiles())
        {
            if (!attachedFiles.Contains(file.Name))
            {
                attachedFiles.Add(file.Name);
            }
        }
    }

    private void RemoveFile(string fileName)
    {
        attachedFiles.Remove(fileName);
    }

    private async Task ToggleVoice()
    {
        if (voiceState == VoiceState.Idle)
        {
            voiceState = VoiceState.UserSpeaking;
            StateHasChanged();

            try
            {
                var success = await JSRuntime.InvokeAsync<bool>("gramAudio.startVoice", dotNetHelper, "visualizerBars");
                if (!success)
                {
                    voiceState = VoiceState.Idle;
                    StateHasChanged();
                }
            }
            catch (Exception)
            {
                voiceState = VoiceState.Idle;
                StateHasChanged();
            }
        }
        else
        {
            await StopVoice();
        }
    }

    private async Task StopVoice()
    {
        voiceCts?.Cancel();
        voiceCts = null;
        voiceState = VoiceState.Idle;

        try
        {
            await JSRuntime.InvokeVoidAsync("gramAudio.stopVoice", "visualizerBars");
        }
        catch (Exception) {}
    }

    [JSInvokable]
    public async Task OnTranscriptReceived(string transcript)
    {
        if (!string.IsNullOrWhiteSpace(transcript))
        {
            draft = transcript;
            StateHasChanged();
            try
            {
                await JSRuntime.InvokeVoidAsync("gramAudio.autoResizeTextarea", textareaRef);
            }
            catch (Exception) {}
        }
    }

    private void HandleKey(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            Send();
        }
    }

    private async void Send()
    {
        var text = draft.Trim();
        var wasVoice = voiceState == VoiceState.UserSpeaking;

        if (string.IsNullOrWhiteSpace(text) && attachedFiles.Count == 0 && !wasVoice)
        {
            return;
        }

        draft = "";

        if (wasVoice)
        {
            await StopVoice();
        }

        var userMessageText = text;
        if (wasVoice && string.IsNullOrWhiteSpace(userMessageText))
        {
            userMessageText = "Voice message";
        }

        if (attachedFiles.Count > 0)
        {
            var filesSuffix = $" [Attached: {string.Join(", ", attachedFiles)}]";
            userMessageText = string.IsNullOrWhiteSpace(userMessageText) ? filesSuffix.Trim() : $"{userMessageText}{filesSuffix}";
            attachedFiles.Clear();
        }

        Active.Messages.Add(new Message("user", userMessageText));

        if (Active.Messages.Count(m => m.Role == "user") == 1)
        {
            Active.Title = userMessageText.Length > 28 ? userMessageText[..28] + "…" : userMessageText;
        }

        Active.Messages.Add(new Message("assistant", "I'm connected and ready."));
        Active.Updated = DateTimeOffset.UtcNow;

        // Gram speaking visualizer animation
        voiceState = VoiceState.GramSpeaking;
        StateHasChanged();

        voiceCts?.Cancel();
        voiceCts = new CancellationTokenSource();
        var token = voiceCts.Token;

        try
        {
            await Task.Delay(2400, token);
            if (!token.IsCancellationRequested)
            {
                voiceState = VoiceState.Idle;
                StateHasChanged();
            }
        }
        catch (TaskCanceledException)
        {
            // Cancelled
        }
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            await StopVoice();
            dotNetHelper?.Dispose();
        }
        catch (Exception) {}
    }
}

