namespace Gram.Blazor.Shared;

public sealed class ThemeDefinition
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Description { get; init; }
    public required string[] Palette { get; init; } // 5 key colors: [Background, Surface, Accent, Highlight, Border]
}

public sealed class ThemeService
{
    public event Action? OnChange;

    public string CurrentTheme { get; private set; } = "purple";

    public IReadOnlyList<ThemeDefinition> AvailableThemes { get; } = new List<ThemeDefinition>
    {
        new()
        {
            Id = "purple",
            Name = "Obsidian Purple",
            Description = "Deep midnight black with electric violet accents",
            Palette = ["#07050a", "#120e1b", "#9333ea", "#c084fc", "#241b36"]
        },
        new()
        {
            Id = "amber",
            Name = "Carbon Amber",
            Description = "Deep charcoal with warm amber accents",
            Palette = ["#0a0a08", "#171612", "#d97706", "#fbbf24", "#302b1c"]
        },
        new()
        {
            Id = "emerald",
            Name = "Cyber Emerald",
            Description = "Pure black with vibrant cyber green accents",
            Palette = ["#050a07", "#0d1811", "#059669", "#34d399", "#172e21"]
        },
        new()
        {
            Id = "blue",
            Name = "Nordic Slate",
            Description = "Cold deep navy with arctic blue accents",
            Palette = ["#06090e", "#0f1622", "#2563eb", "#60a5fa", "#1a2538"]
        },
        new()
        {
            Id = "crimson",
            Name = "Velvet Crimson",
            Description = "Dark obsidian with rich rose accents",
            Palette = ["#0a0507", "#180d12", "#e11d48", "#fb7185", "#331622"]
        }
    };

    public void SetTheme(string themeId)
    {
        if (CurrentTheme != themeId && AvailableThemes.Any(t => t.Id == themeId))
        {
            CurrentTheme = themeId;
            OnChange?.Invoke();
        }
    }
}

