@page "/settings"
@rendermode InteractiveServer
@inject Gram.Blazor.Shared.ThemeService ThemeService

<PageTitle>Settings · Gram</PageTitle>

<div class="settings-layout">
    <aside class="settings-sidebar">
        <div class="settings-nav-title">Settings</div>
        <div class="settings-search-box">
            <input class="settings-search-input" @bind="search" @bind:event="oninput" placeholder="Search settings..." />
        </div>
        <nav class="settings-nav-list">
            @foreach (var item in VisibleGroups)
            {
                <button class="settings-nav-item @(activeGroup == item ? "active" : "")" @onclick="() => activeGroup = item">
                    @item
                </button>
            }
        </nav>
    </aside>

    <section class="settings-content-area">
        <div class="settings-header">
            <h2 class="settings-section-title">@activeGroup</h2>
        </div>

        @if (activeGroup == "General")
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Name</label>
                    <input class="setting-input" @bind="assistantName" />
                    <span class="setting-hint">What Gram calls itself in conversation.</span>
                </div>
            </div>

            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Memory limit</label>
                    <div class="setting-readonly">2 GB</div>
                    <span class="setting-hint">Target memory budget for background processes.</span>
                </div>
            </div>
        }
        else if (activeGroup == "Themes")
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Theme</label>
                    <span class="setting-hint">Choose a 5-color palette for the interface.</span>
                    <div class="theme-grid">
                        @foreach (var theme in ThemeService.AvailableThemes)
                        {
                            <div class="theme-card @(ThemeService.CurrentTheme == theme.Id ? "active" : "")"
                                 @onclick="() => ThemeService.SetTheme(theme.Id)">
                                <div class="theme-card-header">
                                    <span class="theme-name">@theme.Name</span>
                                    @if (ThemeService.CurrentTheme == theme.Id)
                                    {
                                        <span class="theme-active-tag">Active</span>
                                    }
                                </div>
                                <p class="theme-desc">@theme.Description</p>
                                <div class="theme-swatches">
                                    @foreach (var color in theme.Palette)
                                    {
                                        <span class="swatch-dot" style="background-color: @color;" title="@color"></span>
                                    }
                                </div>
                            </div>
                        }
                    </div>
                </div>
            </div>
        }
        else if (activeGroup == "Models")
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Local model</label>
                    <div class="setting-readonly">qwen3.5:9b (Ollama)</div>
                    <span class="setting-hint">Runs on your machine for quick answers and offline work.</span>
                </div>
            </div>

            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Cloud provider</label>
                    <div class="setting-readonly">OpenRouter</div>
                    <span class="setting-hint">Used when handling heavier tasks that need larger models.</span>
                </div>
            </div>
        }
        else if (activeGroup == "Audio")
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Microphone and speaker</label>
                    <div class="setting-readonly">System default</div>
                    <span class="setting-hint">Uses your computer's default audio input and output.</span>
                    <div>
                        <button class="btn-secondary">Test audio</button>
                    </div>
                </div>
            </div>
        }
        else if (activeGroup == "MCP")
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Connected tools</label>
                    <div class="setting-readonly">No servers connected</div>
                    <span class="setting-hint">Model Context Protocol servers let Gram interact with other apps.</span>
                    <div>
                        <button class="btn-secondary">Add server</button>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="settings-card">
                <div class="setting-row">
                    <label class="setting-label">Logs</label>
                    <div class="setting-hint">Activity and error logs stored on this machine.</div>
                    <div>
                        <a class="link-action" href="/api/logs/gram.log" target="_blank">Open latest log ↗</a>
                    </div>
                </div>
            </div>
        }
    </section>
</div>

@code {
    private string search = "";
    private string activeGroup = "General";
    private string assistantName = "Gram";
    private readonly string[] groups = ["General", "Themes", "Models", "Audio", "MCP", "Logs"];
    private IEnumerable<string> VisibleGroups => groups.Where(x => string.IsNullOrWhiteSpace(search) || x.Contains(search, StringComparison.OrdinalIgnoreCase));
}

