args.ReplacementContent:
.settings-sidebar {
  background: var(--bg-panel-subtle);
  border-right: 1px solid var(--border-color);
  padding: 16px;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.settings-sidebar-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow-y: auto;
}

.settings-sidebar-footer {
  padding-top: 14px;
  border-top: 1px solid var(--border-color);
  margin-top: auto;
}

.btn-sidebar-save {
  width: 100%;
  background: var(--accent);
  color: #ffffff;
  border: none;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn-sidebar-save:hover {
  background: var(--accent-hover);
}

.btn-sidebar-save.saved {
  background: var(--success);
}

.settings-content-area {
  padding: 32px 48px;
  overflow-y: auto;
  max-width: 860px;
}

.settings-header {
  margin-bottom: 24px;
}

.settings-section-title {
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 6px 0;
  color: #ffffff;
}

/* Clean Settings List / Rows */
.settings-group {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border-color);
}

.setting-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--border-color);
  gap: 24px;
}

.setting-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
}

.setting-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.setting-desc {
  font-size: 12.5px;
  color: var(--text-muted);
}

.setting-control {
  min-width: 200px;
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.setting-input {
  width: 220px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
}

.setting-input:focus {
  border-color: var(--border-focus);
}

.setting-value {
  font-size: 13px;
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-hover);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-secondary:hover {
  background: var(--bg-active);
}

.link-action {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--accent-text);
  text-decoration: none;
  font-size: 12.5px;
}

.link-action:hover {
  text-decoration: underline;
}

/* Theme List in Settings */
.theme-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.theme-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.theme-row:hover {
  background: var(--bg-hover);
  border-color: rgba(255, 255, 255, 0.12);
}

.theme-row.selected {
  border-color: var(--accent);
  background: var(--bg-active);
}

.theme-row-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.theme-row-name {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.theme-row-desc {
  font-size: 12px;
  color: var(--text-muted);
}

