<PageTitle>Settings · Gram</PageTitle>

<div class="settings-layout">
    <aside class="settings-sidebar">
        <div class="settings-sidebar-body">
            <div class="settings-nav-title">Settings</div>
            <div class="settings-search-box">
                <input class="settings-search-input" @bind="search" @bind:event="oninput" placeholder="Search..." />
            </div>
            <nav class="settings-nav-list">
                @foreach (var item in VisibleGroups)
                {
                    <button class="settings-nav-item @(activeGroup == item ? "active" : "")" @onclick="() => activeGroup = item">
                        @item
                    </button>
                }
            </nav>
        </div>

        <div class="settings-sidebar-footer">
            <button class="btn-sidebar-save @(isSaved ? "saved" : "")" @onclick="SaveSettings">
                @(isSaved ? "Saved" : "Save changes")
            </button>
        </div>
    </aside>

    <section class="settings-content-area">
        <div class="settings-header">
            <h2 class="settings-section-title">@activeGroup</h2>
        </div>

        @if (activeGroup == "General")
        {
            <div class="settings-group">
                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Name</span>
                        <span class="setting-desc">What Gram calls itself in conversation.</span>
                    </div>
                    <div class="setting-control">
                        <input class="setting-input" @bind="assistantName" />
                    </div>
                </div>

                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Memory limit</span>
                        <span class="setting-desc">Target memory budget for background processes.</span>
                    </div>
                    <div class="setting-control">
                        <span class="setting-value">2 GB</span>
                    </div>
                </div>
            </div>
        }
        else if (activeGroup == "Themes")
        {
            <div class="theme-list">
                @foreach (var theme in ThemeService.AvailableThemes)
                {
                    <div class="theme-row @(ThemeService.CurrentTheme == theme.Id ? "selected" : "")"
                         @onclick="() => ThemeService.SetTheme(theme.Id)">
                        <div class="theme-row-info">
                            <span class="theme-row-name">@theme.Name</span>
                            <span class="theme-row-desc">@theme.Description</span>
                        </div>
                        <div class="theme-swatches">
                            @foreach (var color in theme.Palette)
                            {
                                <span class="swatch-dot" style="background-color: @color;" title="@color"></span>
                            }
                        </div>
                    </div>
                }
            </div>
        }
        else if (activeGroup == "Models")
        {
            <div class="settings-group">
                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Local model</span>
                        <span class="setting-desc">Runs on your machine for quick answers and offline work.</span>
                    </div>
                    <div class="setting-control">
                        <span class="setting-value">qwen3.5:9b (Ollama)</span>
                    </div>
                </div>

                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Cloud provider</span>
                        <span class="setting-desc">Used when handling heavier tasks that need larger models.</span>
                    </div>
                    <div class="setting-control">
                        <span class="setting-value">OpenRouter</span>
                    </div>
                </div>
            </div>
        }
        else if (activeGroup == "Audio")
        {
            <div class="settings-group">
                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Microphone and speaker</span>
                        <span class="setting-desc">Uses your computer's default audio devices.</span>
                    </div>
                    <div class="setting-control">
                        <button class="btn-secondary">Test audio</button>
                    </div>
                </div>
            </div>
        }
        else if (activeGroup == "MCP")
        {
            <div class="settings-group">
                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">Connected tools</span>
                        <span class="setting-desc">Model Context Protocol servers let Gram interact with local tools.</span>
                    </div>
                    <div class="setting-control">
                        <button class="btn-secondary">Add server</button>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="settings-group">
                <div class="setting-item">
                    <div class="setting-info">
                        <span class="setting-title">System logs</span>
                        <span class="setting-desc">Activity and error logs stored on this machine.</span>
                    </div>
                    <div class="setting-control">
                        <a class="link-action" href="/api/logs/gram.log" target="_blank">Open latest log ↗</a>
                    </div>
                </div>
            </div>
        }
    </section>
</div>

@code {
    private string search = "";
    private string activeGroup = "General";
    private string assistantName = "Gram";
    private bool isSaved = false;
    private readonly string[] groups = ["General", "Themes", "Models", "Audio", "MCP", "Logs"];
    private IEnumerable<string> VisibleGroups => groups.Where(x => string.IsNullOrWhiteSpace(search) || x.Contains(search, StringComparison.OrdinalIgnoreCase));

    private async Task SaveSettings()
    {
        isSaved = true;
        StateHasChanged();
        await Task.Delay(1800);
        isSaved = false;
        StateHasChanged();
    }
}

