.swatch-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.12);
  flex-shrink: 0;
}

/* Sub-Navigation Tabs */
.subnav-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}

.subnav-tab {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.subnav-tab:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.subnav-tab.active {
  color: var(--text-primary);
  background: var(--bg-active);
  border-color: var(--border-color);
  font-weight: 600;
}

/* Models List */
.models-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.models-search {
  flex: 1;
  max-width: 320px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 12px;
  color: var(--text-primary);
  font-size: 12.5px;
  outline: none;
}

.models-search:focus {
  border-color: var(--border-focus);
}

.btn-primary-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #ffffff);
  border: none;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.btn-primary-action:hover {
  opacity: 0.9;
}

.models-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.model-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  transition: all 0.15s ease;
}

.model-item:hover {
  background: var(--bg-hover);
}

.model-item-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.star-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 16px;
  cursor: pointer;
  padding: 0;
  line-height: 1;
  transition: color 0.15s ease;
}

.star-btn:hover {
  color: #fbbf24;
}

.star-btn.active {
  color: #fbbf24;
}

.model-info-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.model-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.model-name {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.model-id-badge {
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.model-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11.5px;
  color: var(--text-muted);
}

.model-provider-badge {
  color: var(--text-secondary);
  font-weight: 500;
}

.model-item-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-remove-model {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 12px;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  transition: color 0.15s ease;
}

.btn-remove-model:hover {
  color: var(--danger);
}

/* Provider Cards */
.providers-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.provider-card {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.provider-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.provider-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.provider-title {
  font-size: 14.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.provider-status {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}

.provider-status.connected {
  background: var(--success-bg);
  color: var(--success);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.provider-status.disconnected {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

.provider-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.provider-input-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.provider-input {
  flex: 1;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
}

.provider-input:focus {
  border-color: var(--border-focus);
}

.provider-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Modal Dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.modal-dialog {
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 680px;
  max-height: 82vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.modal-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.btn-close-modal {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 16px;
  padding: 4px;
  line-height: 1;
}

.btn-close-modal:hover {
  color: var(--text-primary);
}

.modal-search-bar {
  padding: 12px 20px 8px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.modal-search-input {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
}

.modal-search-input:focus {
  border-color: var(--border-focus);
}

.filter-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.filter-chip {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11.5px;
  padding: 3px 10px;
  border-radius: 9999px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.filter-chip:hover {
  color: var(--text-primary);
  border-color: var(--border-focus);
}

.filter-chip.active {
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #ffffff);
  border-color: transparent;
  font-weight: 500;
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 10px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 240px;
}

.discovery-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.discovery-row:hover {
  background: var(--bg-hover);
}

.discovery-row.selected {
  border-color: var(--border-focus);
  background: var(--bg-active);
}

.discovery-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.discovery-checkbox {
  accent-color: var(--btn-primary-bg, var(--accent));
  width: 15px;
  height: 15px;
  cursor: pointer;
}

.modal-footer {
  padding: 12px 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel-subtle);
}

.modal-footer-stats {
  font-size: 12px;
  color: var(--text-muted);
}

.modal-footer-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

