private void LoadSecureKeys()
{
    try
    {
        if (File.Exists(secureKeysPath))
        {
            var bytes = File.ReadAllBytes(secureKeysPath);
            string json;
            if (OperatingSystem.IsWindows())
            {
                try
                {
                    var unprotected = ProtectedData.Unprotect(bytes, null, DataProtectionScope.CurrentUser);
                    json = Encoding.UTF8.GetString(unprotected);
                }
                catch
                {
                    json = Encoding.UTF8.GetString(bytes);
                }
            }
            else
            {
                json = Encoding.UTF8.GetString(bytes);
            }

            var dict = JsonSerializer.Deserialize<Dictionary<string, string>>(json);
            if (dict != null)
            {
                foreach (var (k, v) in dict)
                {
                    secureKeys[k] = v;
                }
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[ModelService] Error loading secure keys: {ex.Message}");
    }
}

private void SaveSecureKeys()
{
    try
    {
        var json = JsonSerializer.Serialize(secureKeys);
        var bytes = Encoding.UTF8.GetBytes(json);

        if (OperatingSystem.IsWindows())
        {
            try
            {
                bytes = ProtectedData.Protect(bytes, null, DataProtectionScope.CurrentUser);
            }
            catch
            {
                // Fallback to direct bytes if DPAPI not available in environment
            }
        }

        File.WriteAllBytes(secureKeysPath, bytes);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[ModelService] Error saving secure keys: {ex.Message}");
    }
}

public string? GetApiKey(string providerId)
{
    return secureKeys.TryGetValue(providerId, out var key) ? key : null;
}

