using System.Text.Json;
using System.Text.Json.Serialization;

namespace Gram.Blazor.Shared;

public sealed class EnvironmentSettings
{
    [JsonPropertyName("features")]
    public Dictionary<string, bool> Features { get; set; } = new(StringComparer.OrdinalIgnoreCase);

    [JsonPropertyName("settings")]
    public Dictionary<string, string> Settings { get; set; } = new(StringComparer.OrdinalIgnoreCase);
}

public sealed class AppSettingsRoot
{
    [JsonPropertyName("activeEnvironment")]
    public string ActiveEnvironment { get; set; } = "Development";

    [JsonPropertyName("environments")]
    public Dictionary<string, EnvironmentSettings> Environments { get; set; } = new(StringComparer.OrdinalIgnoreCase);
}

public sealed class SettingsService
{
    public event Action? OnChange;

    private readonly string storageDir;
    private readonly string settingsJsonPath;

    public AppSettingsRoot State { get; private set; } = new();

    public string ActiveEnvironment
    {
        get => State.ActiveEnvironment;
        set
        {
            if (State.ActiveEnvironment != value && State.Environments.ContainsKey(value))
            {
                State.ActiveEnvironment = value;
                SaveSettings();
            }
        }
    }

    public EnvironmentSettings Current => State.Environments.TryGetValue(State.ActiveEnvironment, out var env)
        ? env
        : State.Environments.GetValueOrDefault("Development") ?? new EnvironmentSettings();

    public SettingsService()
    {
        var appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
        storageDir = Path.Combine(appData, "Gram");
        settingsJsonPath = Path.Combine(storageDir, "settings.json");

        Directory.CreateDirectory(storageDir);
        LoadSettings();
    }

    public void LoadSettings()
    {
        try
        {
            if (File.Exists(settingsJsonPath))
            {
                var json = File.ReadAllText(settingsJsonPath);
                var root = JsonSerializer.Deserialize<AppSettingsRoot>(json);
                if (root != null && root.Environments.Count > 0)
                {
                    State = root;
                    return;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[SettingsService] Error loading settings.json: {ex.Message}");
        }

        // Initialize default multi-environment configuration
        State = new AppSettingsRoot
        {
            ActiveEnvironment = "Development",
            Environments = new Dictionary<string, EnvironmentSettings>(StringComparer.OrdinalIgnoreCase)
            {
                ["Development"] = new EnvironmentSettings
                {
                    Features = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["wakeWord"] = true,
                        ["webSearch"] = true,
                        ["localWorkspaceAccess"] = true,
                        ["mcpServers"] = true,
                        ["detailedLogs"] = true,
                        ["ollamaLocal"] = true,
                        ["openRouter"] = true,
                        ["systemStartup"] = false,
                        ["audioChime"] = true
                    },
                    Settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["assistantName"] = "Gram (Dev)",
                        ["personaTone"] = "programmer",
                        ["wakeWord"] = "Hey Gram",
                        ["globalHotkey"] = "Alt + Space",
                        ["autoSendVoice"] = "true",
                        ["playVoiceChime"] = "true",
                        ["startAtLogin"] = "false"
                    }
                },
                ["Production"] = new EnvironmentSettings
                {
                    Features = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["wakeWord"] = true,
                        ["webSearch"] = true,
                        ["localWorkspaceAccess"] = false,
                        ["mcpServers"] = true,
                        ["detailedLogs"] = false,
                        ["ollamaLocal"] = false,
                        ["openRouter"] = true,
                        ["systemStartup"] = true,
                        ["audioChime"] = true
                    },
                    Settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["assistantName"] = "Gram",
                        ["personaTone"] = "concise",
                        ["wakeWord"] = "Hey Gram",
                        ["globalHotkey"] = "Alt + Space",
                        ["autoSendVoice"] = "true",
                        ["playVoiceChime"] = "true",
                        ["startAtLogin"] = "true"
                    }
                },
                ["Desktop-Mac"] = new EnvironmentSettings
                {
                    Features = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["wakeWord"] = true,
                        ["webSearch"] = true,
                        ["localWorkspaceAccess"] = true,
                        ["mcpServers"] = true,
                        ["detailedLogs"] = true,
                        ["ollamaLocal"] = true,
                        ["openRouter"] = true,
                        ["systemStartup"] = true,
                        ["audioChime"] = true
                    },
                    Settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["assistantName"] = "Gram",
                        ["personaTone"] = "concise",
                        ["wakeWord"] = "Hey Gram",
                        ["globalHotkey"] = "Cmd + Space",
                        ["autoSendVoice"] = "true",
                        ["playVoiceChime"] = "true",
                        ["startAtLogin"] = "true"
                    }
                }
            }
        };

        SaveSettings();
    }

    public void SaveSettings()
    {
        try
        {
            var json = JsonSerializer.Serialize(State, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(settingsJsonPath, json);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[SettingsService] Error saving settings.json: {ex.Message}");
        }
        OnChange?.Invoke();
    }

    public bool IsFeatureEnabled(string featureKey)
    {
        return Current.Features.TryGetValue(featureKey, out var enabled) && enabled;
    }

    public void SetFeatureEnabled(string featureKey, bool enabled)
    {
        Current.Features[featureKey] = enabled;
        SaveSettings();
    }

    public string GetSetting(string key, string defaultValue = "")
    {
        return Current.Settings.TryGetValue(key, out var val) ? val : defaultValue;
    }

    public void SetSetting(string key, string value)
    {
        Current.Settings[key] = value;
        SaveSettings();
    }

    public void SwitchEnvironment(string envName)
    {
        if (State.Environments.ContainsKey(envName))
        {
            State.ActiveEnvironment = envName;
            SaveSettings();
        }
    }
}

