args.ReplacementContent:
/* Unboxed Theme List in Settings */
.theme-section-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 4px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-color);
}

.theme-subtitle {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.theme-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-top: 0;
  border-bottom: 1px solid var(--border-color);
}

.theme-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 10px;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border-color);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.15s ease;
}

.theme-row:last-child {
  border-bottom: none;
}

.theme-row:hover {
  background: var(--bg-hover);
}

.theme-row.selected {
  background: var(--bg-active);
}

.theme-row-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.theme-radio-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1.5px solid var(--border-focus);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.theme-row.selected .theme-radio-dot {
  border-color: var(--btn-primary-bg, var(--accent));
  background: var(--btn-primary-bg, var(--accent));
}

.theme-row.selected .theme-radio-dot::after {
  content: "";
  width: 4px;
  height: 4px;
  background: #000000;
  border-radius: 50%;
}

.theme-row-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.theme-row-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
}

.theme-row-desc {
  font-size: 11.5px;
  color: var(--text-muted);
}

/* Subtle Confirm Modal */
.modal-dialog-confirm {
  width: 420px;
  max-width: 90vw;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.4);
}

.confirm-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.confirm-message {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.confirm-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 6px;
}

.btn-danger-subtle {
  background: transparent;
  color: #ef4444;
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-danger-subtle:hover {
  background: rgba(239, 68, 68, 0.12);
  border-color: #ef4444;
}

/* Responsive */
@media (max-width: 768px) {

