/* Modal Dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: modalBackdropFadeIn 0.15s ease-out forwards;
}

@keyframes modalBackdropFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modalEntrance {
  from {
    opacity: 0;
    transform: scale(0.97) translateY(6px) translateZ(0);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0) translateZ(0);
  }
}

.modal-dialog {
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 680px;
  max-height: 82vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
  overflow: hidden;
  animation: modalEntrance 0.18s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.modal-dialog-confirm {
  width: 420px;
  max-width: 90vw;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.4);
  animation: modalEntrance 0.18s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform, opacity;
  transform: translateZ(0);
}

.modal-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.btn-close-modal {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 16px;
  padding: 4px;
  line-height: 1;
  border-radius: var(--radius-sm);
  transition: all 0.12s ease;
  transform: translateZ(0);
}

.btn-close-modal:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.btn-close-modal:active {
  transform: scale(0.92) translateZ(0);
}

.modal-search-bar {
  padding: 12px 20px 8px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.modal-search-input {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
  transition: border-color 0.14s ease;
}

.modal-search-input:focus {
  border-color: var(--border-focus);
}

.filter-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.filter-chip {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11.5px;
  padding: 3px 10px;
  border-radius: 9999px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.14s cubic-bezier(0.16, 1, 0.3, 1);
  transform: translateZ(0);
  will-change: transform;
}

.filter-chip:hover {
  color: var(--text-primary);
  border-color: var(--border-focus);
}

.filter-chip:active {
  transform: scale(0.95) translateZ(0);
}

.filter-chip.active {
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #ffffff);
  border-color: transparent;
  font-weight: 500;
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 10px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 240px;
}

.discovery-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 6px;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  transition: background-color 0.12s ease;
  transform: translateZ(0);
}

.discovery-row:hover {
  background: var(--bg-hover);
}

.discovery-row.selected {
  background: var(--bg-active);
}

.discovery-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.discovery-checkbox {
  accent-color: var(--btn-primary-bg, var(--accent));
  width: 15px;
  height: 15px;
  cursor: pointer;
}

.modal-footer {
  padding: 14px 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel-subtle);
}

.modal-footer-stats {
  font-size: 12px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
}

.modal-footer-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Global Hardware Accelerated Micro-Interactions */
button, input, select, textarea {
  -webkit-font-smoothing: antialiased;
}

button:active:not(:disabled),
.btn-primary-action:active:not(:disabled),
.btn-composer-send:active:not(:disabled),
.btn-new-chat:active:not(:disabled),
.btn-secondary:active:not(:disabled),
.btn-sidebar-save:active:not(:disabled) {
  transform: scale(0.982) translateZ(0);
  transition: transform 0.08s cubic-bezier(0.2, 0, 0, 1);
  will-change: transform;
}

.nav-chevron {
  transition: transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform;
  transform: translateZ(0);
}

.nav-chevron.expanded {
  transform: rotate(90deg) translateZ(0);
}

.settings-nav-item, .settings-nav-subitem, .conversation-item, .theme-row {
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: transform, background-color;
  transition: background-color 0.12s cubic-bezier(0.16, 1, 0.3, 1), color 0.12s ease;
}

