  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 860px;
  margin: 0 auto;
  width: 100%;
}

.composer-box {
  flex: 1;
  min-width: 0;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  transition: border-color 0.14s ease;
  box-shadow: none;
}

.composer-box:focus-within {
  border-color: var(--border-focus);
}

.composer-model-section {
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.composer-model-dropdown {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
  padding: 0 10px;
  border-radius: var(--radius-md);
  outline: none;
  cursor: pointer;
  font-family: inherit;
  min-width: 130px;
  max-width: 180px;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: border-color 0.14s ease, background-color 0.14s ease;
  height: 38px;
}

.composer-model-dropdown:hover {
  border-color: var(--border-focus);
  background: var(--bg-hover);
}

.composer-model-dropdown:focus {
  border-color: var(--border-focus);
}

.composer-inner {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
}

.composer-textarea {
  flex: 1;
  min-height: 22px;
  height: 22px;
