args.ReplacementContent:
.composer-dock-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}

.composer-box {
  flex: 1;
  min-width: 0;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 6px 10px;
  transition: border-color 0.14s ease;
  box-shadow: none;
}

.composer-box:focus-within {
  border-color: var(--border-focus);
}

.composer-model-section {
  flex-shrink: 0;
  margin-left: auto;
  display: flex;
  align-items: center;
}

.composer-model-dropdown {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
  padding: 0 10px;
  border-radius: var(--radius-md);
  outline: none;
  cursor: pointer;
  font-family: inherit;
  min-width: 130px;
  max-width: 180px;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: border-color 0.14s ease, background-color 0.14s ease;
  height: 38px;
}

.composer-model-dropdown:hover {
  border-color: var(--border-focus);
  background: var(--bg-hover);
}

.composer-model-dropdown:focus {
  border-color: var(--border-focus);
}

.composer-inner {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
}

.composer-textarea {
  flex: 1;
  min-height: 22px;
  height: 22px;
  max-height: 160px;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13.5px;
  line-height: 22px;
  padding: 0 4px;
  margin: 0;
  display: block;
}

.composer-textarea::placeholder {
  color: var(--text-muted);
}

.composer-actions-left, .composer-actions-right {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  flex-shrink: 0;
}

.btn-composer-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.12s ease;
  padding: 0;
  flex-shrink: 0;
}

.btn-composer-icon:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.btn-composer-icon.voice-btn.active {
  background: var(--accent-light);
  color: var(--accent-text);
  border-color: var(--border-focus);
}

.btn-composer-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #000000);
  border: none;
  cursor: pointer;
  transition: opacity 0.12s ease, transform 0.08s cubic-bezier(0.2, 0, 0, 1);
  padding: 0;
  flex-shrink: 0;
}

.btn-composer-send:hover:not(:disabled) {
  opacity: 0.9;
}

.btn-composer-send:disabled {
  opacity: 0.28;
  cursor: not-allowed;
}

