args.ReplacementContent:
.settings-nav-item, .settings-nav-subitem, .conversation-item, .theme-row {
  transform: translateZ(0);
  backface-visibility: hidden;
  will-change: transform, background-color;
  transition: background-color 0.12s cubic-bezier(0.16, 1, 0.3, 1), color 0.12s ease;
}

/* Chat Settings Toggle Button in Chat Header */
.btn-chat-settings-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 12px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
  transform: translateZ(0);
}

.btn-chat-settings-toggle:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-focus);
}

.btn-chat-settings-toggle.active {
  background: var(--bg-active);
  color: var(--text-primary);
  border-color: var(--border-focus);
}

/* Sliding Chat Settings Sheet */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(2px);
  z-index: 900;
  animation: sheetBackdropFade 0.18s ease-out forwards;
}

@keyframes sheetBackdropFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes sheetSlideIn {
  from {
    transform: translateX(100%) translateZ(0);
  }
  to {
    transform: translateX(0) translateZ(0);
  }
}

.chat-settings-sheet {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 400px;
  max-width: 90vw;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-color);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.45);
  animation: sheetSlideIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform;
  transform: translateZ(0);
}

.sheet-header {
  height: 52px;
  padding: 0 18px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel-subtle);
  flex-shrink: 0;
}

.sheet-title-group {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.sheet-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.sheet-subtitle {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 280px;
}

.btn-close-sheet {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.12s ease;
  padding: 0;
}

.btn-close-sheet:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.sheet-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sheet-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.sheet-label {
  font-size: 12px;
