/* Sliding Chat Settings Sheet */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  z-index: 900;
  animation: sheetBackdropFade 0.15s ease-out forwards;
}

@keyframes sheetBackdropFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes sheetSlideIn {
  from {
    transform: translateX(100%) translateZ(0);
  }
  to {
    transform: translateX(0) translateZ(0);
  }
}

.chat-settings-sheet {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 320px;
  max-width: 90vw;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-color);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  animation: sheetSlideIn 0.18s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform;
  transform: translateZ(0);
}

.sheet-header {
  height: 48px;
  padding: 0 16px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel);
  flex-shrink: 0;
}

.sheet-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.btn-close-sheet {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 13px;
  border-radius: var(--radius-sm);
  transition: all 0.12s ease;
  padding: 0;
}

.btn-close-sheet:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.sheet-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sheet-label {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-muted);
}

.sheet-input {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 13px;
  font-family: inherit;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.14s ease;
}

.sheet-input:focus {
  border-color: var(--border-focus);
}

.sheet-select {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 12.5px;
  font-family: inherit;
  color: var(--text-primary);
  outline: none;
  cursor: pointer;
  transition: border-color 0.14s ease;
}

.sheet-select:focus {
  border-color: var(--border-focus);
}

.sheet-textarea {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12.5px;
  line-height: 1.5;
  font-family: inherit;
  color: var(--text-primary);
  outline: none;
  resize: vertical;
  min-height: 80px;
  transition: border-color 0.14s ease;
}

.sheet-textarea:focus {
  border-color: var(--border-focus);
}

args.TargetContent:
/* Sliding Chat Settings Sheet */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(2px);
  z-index: 900;
  animation: sheetBackdropFade 0.18s ease-out forwards;
}

@keyframes sheetBackdropFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes sheetSlideIn {
  from {
    transform: translateX(100%) translateZ(0);
  }
  to {
    transform: translateX(0) translateZ(0);
  }
}

.chat-settings-sheet {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 400px;
  max-width: 90vw;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-color);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.45);
  animation: sheetSlideIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform;
  transform: translateZ(0);
}

.sheet-header {
  height: 52px;
  padding: 0 18px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-panel-subtle);
  flex-shrink: 0;
}

.sheet-title-group {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.sheet-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.sheet-subtitle {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 280px;
}

.btn-close-sheet {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.12s ease;
  padding: 0;
}

.btn-close-sheet:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.sheet-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sheet-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.sheet-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.sheet-badge {
  font-size: 10.5px;
  font-weight: 500;
  background: var(--bg-hover);
  color: var(--text-secondary);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.sheet-active-tag {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--accent-text);
}

.sheet-input {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 7px 10px;
  font-size: 13px;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.14s ease;
}

.sheet-input:focus {
  border-color: var(--border-focus);
}

.sheet-select {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-primary);
  outline: none;
  cursor: pointer;
  transition: border-color 0.14s ease;
}

.sheet-select:focus {
  border-color: var(--border-focus);
}

.sheet-textarea {
  width: 100%;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  font-size: 12.5px;
  line-height: 1.5;
  font-family: var(--font-mono);
  color: var(--text-primary);
  outline: none;
  resize: vertical;
  min-height: 70px;
  transition: border-color 0.14s ease;
}

.sheet-textarea:focus {
  border-color: var(--border-focus);
}

.sheet-help-text {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.4;
}

.sheet-quick-templates {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
}

.quick-template-label {
  font-size: 11px;
  color: var(--text-muted);
}

.btn-quick-tag {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11px;
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.12s ease;
}

.btn-quick-tag:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-focus);
}

.btn-quick-tag.clear-tag {
  color: var(--danger);
  border-color: rgba(239, 68, 68, 0.3);
}

.btn-quick-tag.clear-tag:hover {
  background: rgba(239, 68, 68, 0.1);
}

.sheet-meta-section {
  padding-top: 14px;
  border-top: 1px solid var(--border-color);
  gap: 10px;
}

.sheet-meta-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
}

.meta-label {
  color: var(--text-muted);
}

.meta-val {
  color: var(--text-secondary);
  font-weight: 500;
}

.sheet-danger-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}

.btn-danger-sheet {
  width: 100%;
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.12s ease;
  text-align: center;
}

.btn-danger-sheet:hover {
  background: rgba(239, 68, 68, 0.1);
  color: var(--danger);
  border-color: rgba(239, 68, 68, 0.3);
}

