/* Main Workspace Layout */
.workspace {
  flex: 1;
  display: flex;
  background: var(--bg-panel);
  border: none;
  border-radius: 0;
  overflow: hidden;
  height: 100%;
  width: 100%;
}

/* Sidebar / Rail */
.conversation-rail {
  width: 260px;
  min-width: 260px;
  border-right: 1px solid var(--border-color);
  background: var(--bg-panel-subtle);
  display: flex;
  flex-direction: column;
  padding: 12px 10px;
  overflow: hidden;
  height: 100%;
  animation: railEntranceLeft 0.16s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform;
  transform: translateZ(0);
}

@keyframes railEntranceLeft {
  from {
    opacity: 0.8;
    transform: translateX(-12px) translateZ(0);
  }
  to {
    opacity: 1;
    transform: translateX(0) translateZ(0);
  }
}

.rail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 4px 10px 4px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 8px;
}

.rail-title {
  font-size: 11.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.btn-rail-collapse, .btn-toggle-sidebar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.12s ease;
  padding: 0;
  transform: translateZ(0);
}

.btn-rail-collapse:hover, .btn-toggle-sidebar:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

