using System.Security.Claims;

namespace Gram.Blazor.Shared;

public enum AuthProviderType
{
    None,
    BetterAuth,
    Oidc,
    ProxyHeader
}

public sealed class AuthSettings
{
    public AuthProviderType Provider { get; set; } = AuthProviderType.None;

    // Better Auth settings
    public string BetterAuthUrl { get; set; } = "http://localhost:3000";
    public string? BetterAuthSecret { get; set; }

    // Generic OIDC settings (Authentik, Keycloak, etc.)
    public string? OidcAuthority { get; set; }
    public string? OidcClientId { get; set; }
    public string? OidcClientSecret { get; set; }
    public string OidcScope { get; set; } = "openid profile email";

    // Reverse Proxy Header Auth settings (Authentik / Authelia / Traefik / Nginx)
    public string ProxyUserHeader { get; set; } = "X-authentik-username";
    public string ProxyEmailHeader { get; set; } = "X-authentik-email";
    public string ProxyNameHeader { get; set; } = "X-authentik-name";
}

public sealed class GramUser
{
    public string Id { get; set; } = "local-user";
    public string Name { get; set; } = "Local User";
    public string? Email { get; set; }
    public string? Image { get; set; }
    public bool IsAuthenticated { get; set; } = true;
    public List<string> Roles { get; set; } = ["admin"];

    public ClaimsPrincipal ToClaimsPrincipal()
    {
        if (!IsAuthenticated)
        {
            return new ClaimsPrincipal(new ClaimsIdentity());
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, Id),
            new(ClaimTypes.Name, Name)
        };

        if (!string.IsNullOrEmpty(Email))
        {
            claims.Add(new Claim(ClaimTypes.Email, Email));
        }

        foreach (var role in Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "GramAuth");
        return new ClaimsPrincipal(identity);
    }
}

using System.Net.Http.Headers;
using System.Security.Claims;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Components.Authorization;

namespace Gram.Blazor.Shared;

public interface IAuthService
{
    AuthSettings Settings { get; }
    GramUser CurrentUser { get; }
    Task<GramUser> GetCurrentUserAsync();
    Task<bool> ValidateBetterAuthSessionAsync(string sessionToken);
    Task LogoutAsync();
    event Action? OnAuthStateChanged;
}

public sealed class GramAuthService : IAuthService
{
    private readonly IConfiguration _configuration;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IHttpContextAccessor? _httpContextAccessor;
    private GramUser _currentUser;

    public AuthSettings Settings { get; } = new();
    public GramUser CurrentUser => _currentUser;
    public event Action? OnAuthStateChanged;

    public GramAuthService(
        IConfiguration configuration,
        IHttpClientFactory httpClientFactory,
        IHttpContextAccessor? httpContextAccessor = null)
    {
        _configuration = configuration;
        _httpClientFactory = httpClientFactory;
        _httpContextAccessor = httpContextAccessor;

        // Load configuration from appsettings or environment variables
        var providerStr = _configuration["AUTH_PROVIDER"] ?? _configuration["Auth:Provider"] ?? "None";
        if (Enum.TryParse<AuthProviderType>(providerStr, true, out var parsedProvider))
        {
            Settings.Provider = parsedProvider;
        }

        Settings.BetterAuthUrl = _configuration["BETTER_AUTH_URL"] ?? _configuration["Auth:BetterAuthUrl"] ?? Settings.BetterAuthUrl;
        Settings.BetterAuthSecret = _configuration["BETTER_AUTH_SECRET"] ?? _configuration["Auth:BetterAuthSecret"];
        Settings.OidcAuthority = _configuration["OIDC_AUTHORITY"] ?? _configuration["Auth:OidcAuthority"];
        Settings.OidcClientId = _configuration["OIDC_CLIENT_ID"] ?? _configuration["Auth:OidcClientId"];
        Settings.OidcClientSecret = _configuration["OIDC_CLIENT_SECRET"] ?? _configuration["Auth:OidcClientSecret"];
        Settings.ProxyUserHeader = _configuration["PROXY_USER_HEADER"] ?? _configuration["Auth:ProxyUserHeader"] ?? Settings.ProxyUserHeader;
        Settings.ProxyEmailHeader = _configuration["PROXY_EMAIL_HEADER"] ?? _configuration["Auth:ProxyEmailHeader"] ?? Settings.ProxyEmailHeader;
        Settings.ProxyNameHeader = _configuration["PROXY_NAME_HEADER"] ?? _configuration["Auth:ProxyNameHeader"] ?? Settings.ProxyNameHeader;

        _currentUser = InitializeUser();
    }

    private GramUser InitializeUser()
    {
        switch (Settings.Provider)
        {
            case AuthProviderType.None:
                return new GramUser
                {
                    Id = "local-admin",
                    Name = "Local Admin",
                    Email = "admin@local.gram",
                    IsAuthenticated = true,
                    Roles = ["admin"]
                };

            case AuthProviderType.ProxyHeader when _httpContextAccessor?.HttpContext != null:
                var headers = _httpContextAccessor.HttpContext.Request.Headers;
                var username = headers[Settings.ProxyUserHeader].FirstOrDefault();
                if (!string.IsNullOrEmpty(username))
                {
                    return new GramUser
                    {
                        Id = username,
                        Name = headers[Settings.ProxyNameHeader].FirstOrDefault() ?? username,
                        Email = headers[Settings.ProxyEmailHeader].FirstOrDefault(),
                        IsAuthenticated = true,
                        Roles = ["user"]
                    };
                }
                return new GramUser { IsAuthenticated = false };

            default:
                // For BetterAuth / Oidc, unauthenticated by default until validated
                return new GramUser { IsAuthenticated = false };
        }
    }

    public Task<GramUser> GetCurrentUserAsync()
    {
        return Task.FromResult(_currentUser);
    }

    public async Task<bool> ValidateBetterAuthSessionAsync(string sessionToken)
    {
        if (string.IsNullOrWhiteSpace(sessionToken))
        {
            _currentUser = new GramUser { IsAuthenticated = false };
            OnAuthStateChanged?.Invoke();
            return false;
        }

        try
        {
            var client = _httpClientFactory.CreateClient();
            var request = new HttpRequestMessage(HttpMethod.Get, $"{Settings.BetterAuthUrl.TrimEnd('/')}/api/auth/get-session");
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", sessionToken);
            request.Headers.Add("Cookie", $"better-auth.session_token={sessionToken}");

            var response = await client.SendAsync(request);
            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadAsStringAsync();
                var sessionResponse = JsonSerializer.Deserialize<BetterAuthSessionResponse>(json, new JsonSerializerOptions
                {
                    PropertyNameCaseInsensitive = true
                });

                if (sessionResponse?.User != null)
                {
                    _currentUser = new GramUser
                    {
                        Id = sessionResponse.User.Id,
                        Name = sessionResponse.User.Name ?? sessionResponse.User.Email ?? "Cloud User",
                        Email = sessionResponse.User.Email,
                        Image = sessionResponse.User.Image,
                        IsAuthenticated = true,
                        Roles = ["user"]
                    };
                    OnAuthStateChanged?.Invoke();
                    return true;
                }
            }
        }
        catch (Exception)
        {
            // Network or validation error
        }

        _currentUser = new GramUser { IsAuthenticated = false };
        OnAuthStateChanged?.Invoke();
        return false;
    }

    public Task LogoutAsync()
    {
        if (Settings.Provider != AuthProviderType.None)
        {
            _currentUser = new GramUser { IsAuthenticated = false };
            OnAuthStateChanged?.Invoke();
        }
        return Task.CompletedTask;
    }

    private sealed class BetterAuthSessionResponse
    {
        [JsonPropertyName("user")]
        public BetterAuthUser? User { get; set; }
    }

    private sealed class BetterAuthUser
    {
        [JsonPropertyName("id")]
        public string Id { get; set; } = "";

        [JsonPropertyName("name")]
        public string? Name { get; set; }

        [JsonPropertyName("email")]
        public string? Email { get; set; }

        [JsonPropertyName("image")]
        public string? Image { get; set; }
    }
}

public sealed class GramAuthStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly IAuthService _authService;

    public GramAuthStateProvider(IAuthService authService)
    {
        _authService = authService;
        _authService.OnAuthStateChanged += NotifyStateChanged;
    }

    public override async Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var user = await _authService.GetCurrentUserAsync();
        return new AuthenticationState(user.ToClaimsPrincipal());
    }

    private void NotifyStateChanged()
    {
        NotifyAuthenticationStateChanged(GetAuthenticationStateAsync());
    }

    public void Dispose()
    {
        _authService.OnAuthStateChanged -= NotifyStateChanged;
    }
}

