using System.Text.Json;

namespace Gram.Blazor.Shared;

public sealed class ConversationService
{
    private readonly StorageService _storageService;
    private readonly string _conversationsFilePath;
    private readonly SemaphoreSlim _lock = new(1, 1);

    public List<Conversation> Conversations { get; private set; } = new();
    public event Action? OnChange;

    public ConversationService(StorageService storageService)
    {
        _storageService = storageService;
        _conversationsFilePath = _storageService.GetFilePath("conversations.json");
        LoadConversations();
    }

    public void LoadConversations()
    {
        try
        {
            if (File.Exists(_conversationsFilePath))
            {
                var json = File.ReadAllText(_conversationsFilePath);
                var list = JsonSerializer.Deserialize<List<Conversation>>(json);
                if (list != null && list.Count > 0)
                {
                    Conversations = list;
                    return;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[ConversationService] Error loading conversations: {ex.Message}");
        }

        // Initialize with default conversation if empty
        Conversations = [new Conversation("default", "New chat", DateTimeOffset.UtcNow)];
    }

    public async Task SaveConversationsAsync()
    {
        await _lock.WaitAsync();
        try
        {
            _storageService.EnsureDirectories();
            var json = JsonSerializer.Serialize(Conversations, new JsonSerializerOptions
            {
                WriteIndented = true
            });
            await File.WriteAllTextAsync(_conversationsFilePath, json);
            OnChange?.Invoke();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[ConversationService] Error saving conversations: {ex.Message}");
        }
        finally
        {
            _lock.Release();
        }
    }
}

