private List<Conversation> conversations => ConversationService.Conversations;
private string activeId = "default";
private string draft = "";
private readonly List<string> attachedFiles = new();
private VoiceState voiceState = VoiceState.Idle;
private DotNetObjectReference<Home>? dotNetHelper;
private ElementReference textareaRef;
private CancellationTokenSource? voiceCts;
private string activeModelId = "";
private bool isSidebarOpen = true;
private bool isSettingsSheetOpen = false;

private Conversation Active => conversations.FirstOrDefault(x => x.Id == activeId) ?? conversations.First();
private GramModel? ActiveModel => ModelService.Models.FirstOrDefault(m => m.Id == activeModelId);

protected override void OnInitialized()
{
    dotNetHelper = DotNetObjectReference.Create(this);
    activeId = conversations.FirstOrDefault()?.Id ?? "default";
    var fav = ModelService.Models.FirstOrDefault(m => m.IsFavorite);
    activeModelId = fav?.Id ?? ModelService.Models.FirstOrDefault()?.Id ?? "";
    ChatStateService.ActiveChatTitle = Active.Title;
}

private async Task OnTitleChanged()
{
    ChatStateService.ActiveChatTitle = Active.Title;
    await ConversationService.SaveConversationsAsync();
}

private async Task NewConversation()
{
    var id = Guid.NewGuid().ToString("N")[..8];
    conversations.Insert(0, new Conversation(id, "New chat", DateTimeOffset.UtcNow));
    activeId = id;
    ChatStateService.ActiveChatTitle = Active.Title;
    await ConversationService.SaveConversationsAsync();
}

private void SelectConversation(string id)
{
    activeId = id;
    ChatStateService.ActiveChatTitle = Active.Title;
}

private async Task DeleteConversation(string id)
{
    if (conversations.Count <= 1) return;
    var index = conversations.FindIndex(x => x.Id == id);
    if (index >= 0)
    {
        conversations.RemoveAt(index);
        if (activeId == id)
        {
            activeId = conversations[Math.Min(index, conversations.Count - 1)].Id;
            ChatStateService.ActiveChatTitle = Active.Title;
        }
        await ConversationService.SaveConversationsAsync();
    }
}

private async Task ClearCurrentChat()
{
    Active.Messages.Clear();
    Active.Title = "New chat";
    Active.Updated = DateTimeOffset.UtcNow;
    attachedFiles.Clear();
