@inject Gram.Blazor.Shared.ThemeService ThemeService
@inject Gram.Blazor.Shared.ChatStateService ChatStateService
@inject Gram.Blazor.Shared.SettingsService SettingsService
@inject Gram.Blazor.Shared.IAuthService AuthService
@implements IDisposable

<div class="app-shell" data-theme="@ThemeService.ActiveThemeName.ToLowerInvariant().Replace(" ", "-")" style="@ThemeService.GetInlineCssVariables()">
    <header class="topbar">
        <div class="topbar-left">
            <a class="brand" href="/">Gram</a>
            <nav class="topbar-nav">
                <a class="nav-link @(IsActive("/") ? "active" : "")" href="/">Chat</a>
                <a class="nav-link @(IsActive("/settings") ? "active" : "")" href="/settings">Settings</a>
            </nav>
        </div>

        @if (IsActive("/"))
        {
            <div class="topbar-center">
                <span class="topbar-chat-title">@ChatStateService.ActiveChatTitle</span>
            </div>
        }
        else if (IsActive("/settings"))
        {
            <div class="topbar-center">
                <nav class="breadcrumbs">
                    @for (int i = 0; i < SettingsService.BreadcrumbParts.Count; i++)
                    {
                        var index = i;
                        var part = SettingsService.BreadcrumbParts[index];
                        @if (index > 0)
                        {
                            <span class="breadcrumb-separator">/</span>
                        }
                        <span class="@(index == SettingsService.BreadcrumbParts.Count - 1 ? "breadcrumb-current" : "breadcrumb-part")">@part</span>
                    }
                </nav>
            </div>
        }

        <div class="topbar-right">
            @if (AuthService.Settings.Provider != AuthProviderType.None)
            {
                <div class="topbar-user-status">
                    @if (AuthService.CurrentUser.IsAuthenticated)
                    {
                        <span class="user-pill" title="@AuthService.CurrentUser.Email">
                            <span class="user-avatar-initial">@(AuthService.CurrentUser.Name.FirstOrDefault())</span>
                            <span class="user-name">@AuthService.CurrentUser.Name</span>
                        </span>
                    }
                    else
                    {
                        <a class="btn-topbar-login" href="@(AuthService.Settings.Provider == AuthProviderType.BetterAuth ? $"{AuthService.Settings.BetterAuthUrl}/login" : "/login")">
                            Sign in
                        </a>
                    }
                </div>
            }
        </div>
    </header>
    <main class="page-frame">
        @Body
    </main>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
        ChatStateService.OnChange += StateHasChanged;
        SettingsService.OnBreadcrumbChanged += StateHasChanged;
        AuthService.OnAuthStateChanged += StateHasChanged;
    }

