private async Task CheckHealth(string providerId)
{
    checkingProviders.Add(providerId);
    StateHasChanged();
    try
    {
        var health = await ModelService.CheckProviderHealthAsync(providerId);
        if (selectedProvider != null && selectedProvider.Id.Equals(providerId, StringComparison.OrdinalIgnoreCase))
        {
            currentProviderHealth = health;
        }
    }
    finally
    {
        checkingProviders.Remove(providerId);
        StateHasChanged();
    }
}

private void OpenProviderModal(ProviderConfig prov)
{
    selectedProvider = prov;
    providerBaseUrlInput = prov.BaseUrl ?? "";
    providerKeyInput = ModelService.GetApiKey(prov.Id) ?? "";
    currentProviderHealth = ModelService.GetHealth(prov.Id);
    showProviderKey = false;
    providerCopyFeedback = "";
    showProviderModal = true;
}

private void CloseProviderModal()
{
    showProviderModal = false;
    selectedProvider = null;
}

private void ResetProviderBaseUrl()
{
    if (selectedProvider == null) return;
    providerBaseUrlInput = selectedProvider.Id switch
    {
        "openrouter" => "https://openrouter.ai/api/v1",
        "openai" => "https://api.openai.com/v1",
        "anthropic" => "https://api.anthropic.com/v1",
        "ollama" => "http://localhost:11434",
        "xai" => "https://api.x.ai/v1",
        _ => ""
    };
}

private async Task CopyProviderKey()
{
