                @if (isLoadingDiscovery)
                {
                    <div class="harness-empty-state">
                        <p>Fetching latest models from OpenRouter...</p>
                    </div>
                }
                else if (FilteredDiscoveredModels.Count == 0)
                {
                    <div class="harness-empty-state">
                        <p>No models matching "@discoverySearch"</p>
                    </div>
                }
                else
                {
                    @foreach (var model in FilteredDiscoveredModels)
                    {
                        <div class="discovery-row @(model.IsSelected ? "selected" : "")"
                             @onclick="() => model.IsSelected = !model.IsSelected">
                            <div class="discovery-left">
                                <input type="checkbox"
                                       class="discovery-checkbox"
                                       checked="@model.IsSelected"
                                       @onchange="() => model.IsSelected = !model.IsSelected"
                                       @onclick:stopPropagation="true" />

                                <div class="model-info-block">
                                    <div class="model-title-row">
                                        <span class="model-name">@model.Name</span>
                                        <span class="model-id-badge">@model.Id</span>
                                    </div>
                                    @if (!string.IsNullOrWhiteSpace(model.Description))
                                    {
                                        <span class="setting-desc" style="font-size: 11px;">@model.Description</span>
                                    }
                                </div>
                            </div>

                            <div style="display: flex; align-items: center; gap: 10px;">
                                @if (model.ContextLength.HasValue)
                                {
                                    <span class="setting-hint">@(model.ContextLength.Value >= 1000 ? $"{model.ContextLength.Value / 1000}k context" : $"{model.ContextLength.Value} ctx")</span>
                                }
                                <button class="star-btn @(model.IsFavorite ? "active" : "")"
                                        @onclick="() => model.IsFavorite = !model.IsFavorite"
                                        @onclick:stopPropagation="true"
                                        title="@(model.IsFavorite ? "Favorite" : "Mark favorite")">
                                    @(model.IsFavorite ? "★" : "☆")
                                </button>
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="modal-footer">
                <div class="modal-footer-stats">
                    <span>@discoveredModels.Count(m => m.IsSelected) models selected</span>
                    <button class="btn-subtle" style="margin-left: 8px; font-size: 11px; padding: 2px 6px;" @onclick="ToggleSelectAllFiltered">
                        @(FilteredDiscoveredModels.All(m => m.IsSelected) ? "Deselect Filtered" : "Select Filtered")
                    </button>
                </div>

                <div class="modal-footer-actions">
                    <button class="btn-secondary" style="margin-top: 0;" @onclick="CloseDiscoveryModal">
                        Cancel
                    </button>
                    <button class="btn-primary-action"
                            disabled="@(discoveredModels.Count(m => m.IsSelected) == 0)"
                            @onclick="AddSelectedModels">
                        Add Selected (@discoveredModels.Count(m => m.IsSelected))
                    </button>
                </div>
            </div>
        </div>
    </div>
}

