private void CloseDiscoveryModal()
{
    showDiscoveryModal = false;
}

private void ClearDiscoverySearch()
{
    discoverySearch = "";
}

private void ResetDiscoveryFilters()
{
    discoverySearch = "";
    activeFilterChip = "All";
}

private int GetFilterChipCount(string chip)
{
    if (chip == "All") return discoveredModels.Count;
    return discoveredModels.Count(m =>
        m.Id.Contains(chip, StringComparison.OrdinalIgnoreCase) ||
        m.Name.Contains(chip, StringComparison.OrdinalIgnoreCase));
}

private string GetModelVendor(string modelId)
{
    if (modelId.StartsWith("anthropic/", StringComparison.OrdinalIgnoreCase)) return "Anthropic";
    if (modelId.StartsWith("openai/", StringComparison.OrdinalIgnoreCase)) return "OpenAI";
    if (modelId.StartsWith("deepseek/", StringComparison.OrdinalIgnoreCase)) return "DeepSeek";
    if (modelId.StartsWith("google/", StringComparison.OrdinalIgnoreCase)) return "Google";
    if (modelId.StartsWith("meta-llama/", StringComparison.OrdinalIgnoreCase) || modelId.StartsWith("meta/", StringComparison.OrdinalIgnoreCase)) return "Meta";
    if (modelId.StartsWith("x-ai/", StringComparison.OrdinalIgnoreCase) || modelId.StartsWith("xai/", StringComparison.OrdinalIgnoreCase)) return "xAI";
    if (modelId.StartsWith("qwen/", StringComparison.OrdinalIgnoreCase) || modelId.StartsWith("alibaba/", StringComparison.OrdinalIgnoreCase)) return "Qwen";
    if (modelId.StartsWith("mistralai/", StringComparison.OrdinalIgnoreCase)) return "Mistral";
    if (modelId.StartsWith("cohere/", StringComparison.OrdinalIgnoreCase)) return "Cohere";
    var slashIndex = modelId.IndexOf('/');
    return slashIndex > 0 ? modelId[..slashIndex] : "OpenRouter";
}

private void ToggleSelectAllFiltered()
{
    var filtered = FilteredDiscoveredModels;
    var allSelected = filtered.All(m => m.IsSelected);
    foreach (var m in filtered)
    {
        m.IsSelected = !allSelected;
    }
}

private void AddSelectedModels()
{
    var selected = discoveredModels.Where(m => m.IsSelected).ToList();
    if (selected.Count > 0)
    {
        ModelService.AddModels(selected);
    }
    showDiscoveryModal = false;
    activeCategory = "Intelligence/Models";
}

