/* Markdown Rendering Styles */
.markdown-body-wrapper {
  color: var(--text-primary);
  font-size: 13.5px;
  line-height: 1.6;
}

.markdown-body-wrapper p {
  margin: 0 0 10px 0;
}

.markdown-body-wrapper p:last-child {
  margin-bottom: 0;
}

.markdown-body-wrapper h1,
.markdown-body-wrapper h2,
.markdown-body-wrapper h3,
