/* ==========================================================================
   ShadCN Blazor Design Tokens & Component Styles
   ========================================================================== */

:root {
  /* HSL Colors */
  --background: 0 0% 100%;
  --foreground: 222.2 84% 4.9%;

  --card: 0 0% 100%;
  --card-foreground: 222.2 84% 4.9%;

  --popover: 0 0% 100%;
  --popover-foreground: 222.2 84% 4.9%;

  --primary: 222.2 47.4% 11.2%;
  --primary-foreground: 210 40% 98%;

  --secondary: 210 40% 96.1%;
  --secondary-foreground: 222.2 47.4% 11.2%;

  --muted: 210 40% 96.1%;
  --muted-foreground: 215.4 16.3% 46.9%;

  --accent: 210 40% 96.1%;
  --accent-foreground: 222.2 47.4% 11.2%;

  --destructive: 0 84.2% 60.2%;
  --destructive-foreground: 210 40% 98%;

  --border: 214.3 31.8% 91.4%;
  --input: 214.3 31.8% 91.4%;
  --ring: 222.2 84% 4.9%;

  --radius: 0.5rem;

  --sidebar: var(--background);
  --sidebar-foreground: var(--foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);
}

.dark, [data-theme="dark"], body.dark {
  --background: 222.2 84% 4.9%;
  --foreground: 210 40% 98%;

  --card: 222.2 84% 4.9%;
  --card-foreground: 210 40% 98%;

  --popover: 222.2 84% 4.9%;
  --popover-foreground: 210 40% 98%;

  --primary: 210 40% 98%;
  --primary-foreground: 222.2 47.4% 11.2%;

  --secondary: 217.2 32.6% 17.5%;
  --secondary-foreground: 210 40% 98%;

  --muted: 217.2 32.6% 17.5%;
  --muted-foreground: 215 20.2% 65.1%;

  --accent: 217.2 32.6% 17.5%;
  --accent-foreground: 210 40% 98%;

  --destructive: 0 62.8% 30.6%;
  --destructive-foreground: 210 40% 98%;

  --border: 217.2 32.6% 17.5%;
  --input: 217.2 32.6% 17.5%;
  --ring: 212.7 26.8% 83.9%;

  --sidebar: var(--background);
  --sidebar-foreground: var(--foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);
}

/* ==========================================================================
   ShadCN Button Component
   ========================================================================== */
.shadcn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  border-radius: var(--radius);
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1;
  transition: all 0.15s ease;
  cursor: pointer;
  border: 1px solid transparent;
  outline: none;
  font-family: inherit;
  user-select: none;
  text-decoration: none;
  gap: 8px;
}

.shadcn-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

/* Button Variants */
.shadcn-btn-default {
  background-color: hsl(var(--primary));
  color: hsl(var(--primary-foreground));
}
.shadcn-btn-default:hover {
  opacity: 0.9;
}

.shadcn-btn-destructive {
  background-color: hsl(var(--destructive));
  color: hsl(var(--destructive-foreground));
}
.shadcn-btn-destructive:hover {
  opacity: 0.9;
}

.shadcn-btn-outline {
  border-color: hsl(var(--border));
  background-color: transparent;
  color: hsl(var(--foreground));
}
.shadcn-btn-outline:hover {
  background-color: hsl(var(--accent));
  color: hsl(var(--accent-foreground));
}

.shadcn-btn-secondary {
  background-color: hsl(var(--secondary));
  color: hsl(var(--secondary-foreground));
}
.shadcn-btn-secondary:hover {
  opacity: 0.85;
}

.shadcn-btn-ghost {
  background-color: transparent;
  color: hsl(var(--foreground));
}
.shadcn-btn-ghost:hover {
  background-color: hsl(var(--accent));
  color: hsl(var(--accent-foreground));
}

.shadcn-btn-link {
  background-color: transparent;
  color: hsl(var(--primary));
  text-decoration: underline;
  text-underline-offset: 4px;
}

/* Button Sizes */
.shadcn-btn-size-default {
  height: 36px;
  padding: 0 16px;
}
.shadcn-btn-size-sm {
  height: 30px;
  border-radius: calc(var(--radius) - 2px);
  padding: 0 12px;
  font-size: 12px;
}
.shadcn-btn-size-lg {
  height: 42px;
  border-radius: calc(var(--radius) + 2px);
  padding: 0 24px;
  font-size: 15px;
}
.shadcn-btn-size-icon {
  height: 36px;
  width: 36px;
  padding: 0;
}

/* ==========================================================================
   ShadCN Card Component
   ========================================================================== */
.shadcn-card {
  border-radius: var(--radius);
  border: 1px solid hsl(var(--border));
  background-color: hsl(var(--card));
  color: hsl(var(--card-foreground));
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
}

.shadcn-card-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 24px 24px 16px 24px;
}

.shadcn-card-title {
  font-size: 18px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.015em;
  color: hsl(var(--card-foreground));
  margin: 0;
}

.shadcn-card-description {
  font-size: 13.5px;
  color: hsl(var(--muted-foreground));
  margin: 0;
  line-height: 1.45;
}

.shadcn-card-content {
  padding: 0 24px 24px 24px;
}

.shadcn-card-footer {
  display: flex;
  align-items: center;
  padding: 0 24px 24px 24px;
}

/* ==========================================================================
   ShadCN Alert Component
   ========================================================================== */
.shadcn-alert {
  position: relative;
  width: 100%;
  border-radius: var(--radius);
  border: 1px solid hsl(var(--border));
  padding: 14px 16px;
  font-size: 13.5px;
  background-color: hsl(var(--background));
  color: hsl(var(--foreground));
  box-sizing: border-box;
}

.shadcn-alert-destructive {
  border-color: hsl(var(--destructive) / 0.5);
  color: hsl(var(--destructive));
}

.shadcn-alert-title {
  margin-bottom: 4px;
  font-weight: 600;
  line-height: 1.2;
}

.shadcn-alert-description {
  font-size: 13px;
  line-height: 1.5;
  opacity: 0.9;
}

/* ==========================================================================
   ShadCN Badge Component
   ========================================================================== */
.shadcn-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 9999px;
  border: 1px solid transparent;
  padding: 2px 9px;
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1;
  transition: all 0.15s ease;
  user-select: none;
}

.shadcn-badge-default {
  border-color: transparent;
  background-color: hsl(var(--primary));
  color: hsl(var(--primary-foreground));
}

.shadcn-badge-secondary {
  border-color: transparent;
  background-color: hsl(var(--secondary));
  color: hsl(var(--secondary-foreground));
}

.shadcn-badge-destructive {
  border-color: transparent;
  background-color: hsl(var(--destructive));
  color: hsl(var(--destructive-foreground));
}

.shadcn-badge-outline {
  border-color: hsl(var(--border));
  color: hsl(var(--foreground));
  background-color: transparent;
}

/* ==========================================================================
   ShadCN Input Component
   ========================================================================== */
.shadcn-input {
  display: flex;
  height: 36px;
  width: 100%;
  border-radius: var(--radius);
  border: 1px solid hsl(var(--border));
  background-color: transparent;
  padding: 8px 12px;
  font-size: 13.5px;
  color: hsl(var(--foreground));
  box-sizing: border-box;
  font-family: inherit;
  transition: border-color 0.15s ease;
  outline: none;
}

.shadcn-input:focus {
  border-color: hsl(var(--ring));
}

.shadcn-input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.shadcn-input::placeholder {
  color: hsl(var(--muted-foreground));
}

/* ==========================================================================
   ShadCN Separator Component
   ========================================================================== */
.shadcn-separator {
  flex-shrink: 0;
  background-color: hsl(var(--border));
}

.shadcn-separator-horizontal {
  height: 1px;
  width: 100%;
  margin: 12px 0;
}

.shadcn-separator-vertical {
  height: 100%;
  width: 1px;
  margin: 0 12px;
}

