.sonner-toast-close:hover {
  background: hsl(var(--accent));
  color: hsl(var(--foreground));
}

/* ==========================================================================
   ShadCN Context Menu Component
   ========================================================================== */
.shadcn-context-menu-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9998;
  background: transparent;
}

.shadcn-context-menu {
  position: fixed;
  z-index: 9999;
  min-width: 170px;
  max-width: 260px;
  overflow: hidden;
  border-radius: var(--radius);
  border: 1px solid hsl(var(--border));
  background-color: hsl(var(--popover));
  color: hsl(var(--popover-foreground));
  padding: 4px;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.28), 0 2px 6px rgba(0, 0, 0, 0.12);
  animation: context-menu-pop 0.12s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box;
}

@keyframes context-menu-pop {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.shadcn-context-menu-item {
  position: relative;
  display: flex;
  width: 100%;
  cursor: pointer;
  user-select: none;
  align-items: center;
  gap: 8px;
  border-radius: calc(var(--radius) - 2px);
  padding: 6px 8px;
  font-size: 12.5px;
  outline: none;
  border: none;
  background: transparent;
  color: hsl(var(--foreground));
  text-align: left;
  transition: background-color 0.1s ease, color 0.1s ease;
  font-family: inherit;
  box-sizing: border-box;
}

.shadcn-context-menu-item:hover {
  background-color: hsl(var(--accent));
  color: hsl(var(--accent-foreground));
}

.shadcn-context-menu-item.destructive {
  color: hsl(var(--destructive));
}

.shadcn-context-menu-item.destructive:hover {
  background-color: hsl(var(--destructive));
  color: hsl(var(--destructive-foreground));
}

.shadcn-context-menu-item.disabled {
  pointer-events: none;
  opacity: 0.5;
}

.shadcn-context-menu-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: currentColor;
}

.shadcn-context-menu-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shadcn-context-menu-shortcut {
  margin-left: auto;
  font-size: 10.5px;
  letter-spacing: 0.05em;
  color: hsl(var(--muted-foreground));
}

.shadcn-context-menu-separator {
  height: 1px;
  margin: 4px -4px;
  background-color: hsl(var(--border));
}

