private void OnChatContextMenu(MouseEventArgs e, Conversation chat)
{
    contextMenuTarget = chat;
    contextMenuX = Math.Min(e.ClientX, 230);
    contextMenuY = Math.Min(e.ClientY, 560);
    isContextMenuOpen = true;
}

private void RenameFromContextMenu(Conversation? chat)
{
    isContextMenuOpen = false;
    if (chat == null) return;
    activeId = chat.Id;
    isSettingsSheetOpen = true;
}

private async Task DuplicateFromContextMenu(Conversation? chat)
{
    isContextMenuOpen = false;
    if (chat == null) return;
    var newId = Guid.NewGuid().ToString("N")[..8];
    var duplicate = new Conversation(newId, $"{chat.Title} (Copy)", DateTimeOffset.UtcNow)
    {
        SystemPromptOverride = chat.SystemPromptOverride,
        Rules = chat.Rules
    };

    foreach (var msg in chat.Messages)
    {
        duplicate.Messages.Add(new Message(msg.Role, msg.Text, msg.Timestamp));
    }

    conversations.Insert(0, duplicate);
    activeId = newId;
    ChatStateService.ActiveChatTitle = duplicate.Title;
    await ConversationService.SaveConversationAsync(duplicate);
    SonnerService.Success("Chat duplicated", $"Created copy: {duplicate.Title}");
}

private async Task CopyIdFromContextMenu(Conversation? chat)
{
    isContextMenuOpen = false;
    if (chat == null) return;
    try
    {
        await JSRuntime.InvokeVoidAsync("navigator.clipboard.writeText", chat.Id);
        SonnerService.Info("ID copied", $"Conversation ID: {chat.Id}");
    }
    catch {}
}

private async Task DeleteFromContextMenu(Conversation? chat)
{
    isContextMenuOpen = false;
    if (chat == null) return;
    await DeleteConversation(chat.Id);
    SonnerService.Info("Chat deleted", "The conversation has been removed.");
}

