                    ["content"] = Convert.ToBase64String(Encoding.UTF8.GetBytes(change.Content)),
                    ["branch"] = branch
                };
                if (!string.IsNullOrWhiteSpace(currentSha))
                {
                    payload["sha"] = currentSha;
