    // Git & Version Control Management State
    private bool showGitModal = false;
    private GitAccount? editingGitAccount = null;
    private GitProviderType gitProviderTypeInput = GitProviderType.GitHub;
    private string gitDisplayNameInput = "";
    private string gitInstanceUrlInput = "https://github.com";
    private string gitUsernameInput = "";
    private string gitTokenInput = "";
    private bool gitIsDefaultInput = false;
    private bool showGitToken = false;
    private bool isTestingGitConnection = false;
    private string? testingAccountId = null;

    private GitAccount? selectedGitAccount = null;
    private List<GitRepository>? gitRepositories = null;

    private void OpenAddGitAccountModal()
    {
        editingGitAccount = new GitAccount();
        gitProviderTypeInput = GitProviderType.GitHub;
        gitDisplayNameInput = "My GitHub";
        gitInstanceUrlInput = "https://github.com";
        gitUsernameInput = "";
        gitTokenInput = "";
        gitIsDefaultInput = GitService.Accounts.Count == 0;
        showGitToken = false;
        showGitModal = true;
    }

    private void OnGitProviderTypeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<GitProviderType>(e.Value?.ToString(), out var type))
        {
            gitProviderTypeInput = type;
            var provider = GitService.GetProvider(type);
            gitInstanceUrlInput = provider?.DefaultInstanceUrl ?? "https://github.com";
            gitDisplayNameInput = type switch
            {
                GitProviderType.GitHub => "My GitHub",
                GitProviderType.GitLab => "My GitLab",
                GitProviderType.Forgejo => "Codeberg / Forgejo",
                GitProviderType.Bitbucket => "My Bitbucket",
                _ => "Git Account"
            };
        }
    }

    private void EditGitAccount(GitAccount account)
    {
        editingGitAccount = account;
        gitProviderTypeInput = account.ProviderType;
        gitDisplayNameInput = account.DisplayName;
        gitInstanceUrlInput = account.InstanceUrl;
        gitUsernameInput = account.Username;
        gitTokenInput = account.Token;
        gitIsDefaultInput = account.IsDefault;
        showGitToken = false;
        showGitModal = true;
    }

    private async Task TestDraftGitConnection()
    {
        isTestingGitConnection = true;
        StateHasChanged();
        try
        {
            var temp = new GitAccount
            {
                ProviderType = gitProviderTypeInput,
                InstanceUrl = gitInstanceUrlInput,
                Username = gitUsernameInput,
                Token = gitTokenInput
            };
            var success = await GitService.TestConnectionAsync(temp);
            if (success)
            {
                SonnerService.Success("Connection successful", $"Authenticated with {gitProviderTypeInput}");
            }
            else
            {
                SonnerService.Error("Connection failed", "Could not authenticate with provided token/URL");
            }
        }
        catch (Exception ex)
        {
            SonnerService.Error("Verification error", ex.Message);
        }
        finally
        {
            isTestingGitConnection = false;
            StateHasChanged();
        }
    }

    private async Task TestGitConnection(GitAccount account)
    {
        isTestingGitConnection = true;
        testingAccountId = account.Id;
        StateHasChanged();
        try
        {
            var success = await GitService.TestConnectionAsync(account);
            if (success)
            {
                SonnerService.Success("Connection verified", $"{account.DisplayName} is active and valid");
            }
            else
            {
                SonnerService.Error("Connection failed", $"Could not reach {account.InstanceUrl}");
            }
        }
        catch (Exception ex)
        {
            SonnerService.Error("Verification error", ex.Message);
        }
        finally
        {
            isTestingGitConnection = false;
            testingAccountId = null;
            StateHasChanged();
        }
    }

    private async Task SaveGitAccount()
    {
        if (string.IsNullOrWhiteSpace(gitDisplayNameInput))
        {
            gitDisplayNameInput = $"{gitProviderTypeInput} Account";
        }

        var account = editingGitAccount ?? new GitAccount();
        account.ProviderType = gitProviderTypeInput;
        account.DisplayName = gitDisplayNameInput.Trim();
        account.InstanceUrl = gitInstanceUrlInput.Trim();
        account.Username = gitUsernameInput.Trim();
        account.Token = gitTokenInput.Trim();
        account.IsDefault = gitIsDefaultInput;

        await GitService.SaveAccountAsync(account);
        showGitModal = false;
        SonnerService.Success("Account saved", $"Saved Git account: {account.DisplayName}");
    }

    private async Task DeleteGitAccount(GitAccount account)
    {
        await GitService.DeleteAccountAsync(account.Id);
        if (selectedGitAccount?.Id == account.Id)
        {
            selectedGitAccount = null;
            gitRepositories = null;
        }
        SonnerService.Info("Account removed", $"Removed {account.DisplayName}");
    }

    private async Task ExploreRepositories(GitAccount account)
    {
        selectedGitAccount = account;
        gitRepositories = null;
        StateHasChanged();
        try
        {
            var provider = GitService.GetProvider(account.ProviderType);
            if (provider != null)
            {
                gitRepositories = await provider.ListRepositoriesAsync(account);
                SonnerService.Info("Repositories loaded", $"Found {gitRepositories.Count} repositories");
            }
        }
        catch (Exception ex)
        {
            SonnerService.Error("Error loading repositories", ex.Message);
        }
        StateHasChanged();
    }

    public void Dispose()
    {
        ModelService.OnChange -= StateHasChanged;
        SettingsService.OnChange -= StateHasChanged;
        GitService.OnChange -= StateHasChanged;
    }
}

