using System.Security.Claims;
using System.Text.Json.Serialization;

namespace Gram.Blazor.Shared;

public enum AuthProviderType
{
    None,
    BetterAuth,
    Oidc,
    ProxyHeader
}

public sealed class AuthSettings
{
    public AuthProviderType Provider { get; set; } = AuthProviderType.None;

    // Better Auth settings
    public string BetterAuthUrl { get; set; } = "http://localhost:3000";
    public string? BetterAuthSecret { get; set; }

    // Generic OIDC settings (Authentik, Keycloak, etc.)
    public string? OidcAuthority { get; set; }
    public string? OidcClientId { get; set; }
    public string? OidcClientSecret { get; set; }
    public string OidcScope { get; set; } = "openid profile email";

    // Reverse Proxy Header Auth settings (Authentik / Authelia / Traefik / Nginx)
    public string ProxyUserHeader { get; set; } = "X-authentik-username";
    public string ProxyEmailHeader { get; set; } = "X-authentik-email";
    public string ProxyNameHeader { get; set; } = "X-authentik-name";
}

public sealed class GramUser
{
    public string Id { get; set; } = "local-admin";
    public string Name { get; set; } = "Local Admin";
    public string? Email { get; set; } = "admin@local.gram";
    public string? Image { get; set; }
    public bool IsAuthenticated { get; set; } = true;
    public List<string> Roles { get; set; } = ["admin"];
    public string? SessionToken { get; set; }
    public DateTimeOffset? ExpiresAt { get; set; }

    public ClaimsPrincipal ToClaimsPrincipal()
    {
        if (!IsAuthenticated)
        {
            return new ClaimsPrincipal(new ClaimsIdentity());
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, Id),
            new(ClaimTypes.Name, Name)
        };

        if (!string.IsNullOrEmpty(Email))
        {
            claims.Add(new Claim(ClaimTypes.Email, Email));
        }

        foreach (var role in Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "GramAuth");
        return new ClaimsPrincipal(identity);
    }
}

public sealed class AuthResult
{
    public bool Success { get; set; }
    public string? ErrorMessage { get; set; }
    public GramUser? User { get; set; }
    public string? Token { get; set; }
}

public sealed class BetterAuthSessionResponse
{
    [JsonPropertyName("session")]
    public BetterAuthSession? Session { get; set; }

    [JsonPropertyName("user")]
    public BetterAuthUser? User { get; set; }
}

public sealed class BetterAuthSession
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = "";

    [JsonPropertyName("token")]
    public string? Token { get; set; }

    [JsonPropertyName("userId")]
    public string UserId { get; set; } = "";

    [JsonPropertyName("expiresAt")]
    public DateTimeOffset? ExpiresAt { get; set; }
}

public sealed class BetterAuthUser
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = "";

    [JsonPropertyName("name")]
    public string? Name { get; set; }

    [JsonPropertyName("email")]
    public string? Email { get; set; }

    [JsonPropertyName("image")]
    public string? Image { get; set; }

    [JsonPropertyName("role")]
    public string? Role { get; set; }
}

using System.Net.Http.Headers;
using System.Security.Claims;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Components.Authorization;

namespace Gram.Blazor.Shared;

public interface IAuthService
{
    AuthSettings Settings { get; }
    GramUser CurrentUser { get; }
    Task<GramUser> GetCurrentUserAsync();
    Task<AuthResult> SignInWithEmailAsync(string email, string password);
    Task<AuthResult> SignUpWithEmailAsync(string name, string email, string password);
    Task<bool> ValidateBetterAuthSessionAsync(string sessionToken);
    string GetSocialLoginUrl(string provider, string callbackUrl);
    Task LogoutAsync();
    Task SetAuthProviderAsync(AuthProviderType provider, string? betterAuthUrl = null);
    event Action? OnAuthStateChanged;
}

public sealed class GramAuthService : IAuthService
{
    private readonly IConfiguration _configuration;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly StorageService _storageService;
    private readonly IHttpContextAccessor? _httpContextAccessor;
    private readonly string _sessionTokenFilePath;
    private GramUser _currentUser;

    public AuthSettings Settings { get; } = new();
    public GramUser CurrentUser => _currentUser;
    public event Action? OnAuthStateChanged;

    public GramAuthService(
        IConfiguration configuration,
        IHttpClientFactory httpClientFactory,
        StorageService storageService,
        IHttpContextAccessor? httpContextAccessor = null)
    {
        _configuration = configuration;
        _httpClientFactory = httpClientFactory;
        _storageService = storageService;
        _httpContextAccessor = httpContextAccessor;
        _sessionTokenFilePath = _storageService.GetFilePath("auth_session.json");

        // Load configuration from appsettings, environment variables, or local config
        var providerStr = _configuration["AUTH_PROVIDER"] ?? _configuration["Auth:Provider"] ?? "None";
        if (Enum.TryParse<AuthProviderType>(providerStr, true, out var parsedProvider))
        {
            Settings.Provider = parsedProvider;
        }

        Settings.BetterAuthUrl = _configuration["BETTER_AUTH_URL"] ?? _configuration["Auth:BetterAuthUrl"] ?? Settings.BetterAuthUrl;
        Settings.BetterAuthSecret = _configuration["BETTER_AUTH_SECRET"] ?? _configuration["Auth:BetterAuthSecret"];
        Settings.OidcAuthority = _configuration["OIDC_AUTHORITY"] ?? _configuration["Auth:OidcAuthority"];
        Settings.OidcClientId = _configuration["OIDC_CLIENT_ID"] ?? _configuration["Auth:OidcClientId"];
        Settings.OidcClientSecret = _configuration["OIDC_CLIENT_SECRET"] ?? _configuration["Auth:OidcClientSecret"];
        Settings.ProxyUserHeader = _configuration["PROXY_USER_HEADER"] ?? _configuration["Auth:ProxyUserHeader"] ?? Settings.ProxyUserHeader;
        Settings.ProxyEmailHeader = _configuration["PROXY_EMAIL_HEADER"] ?? _configuration["Auth:ProxyEmailHeader"] ?? Settings.ProxyEmailHeader;
        Settings.ProxyNameHeader = _configuration["PROXY_NAME_HEADER"] ?? _configuration["Auth:ProxyNameHeader"] ?? Settings.ProxyNameHeader;

        _currentUser = InitializeUser();
        _ = TryRestoreSessionAsync();
    }

    private GramUser InitializeUser()
    {
        switch (Settings.Provider)
        {
            case AuthProviderType.None:
                return new GramUser
                {
                    Id = "local-admin",
                    Name = "Local Admin",
                    Email = "admin@local.gram",
                    IsAuthenticated = true,
                    Roles = ["admin"]
                };

            case AuthProviderType.ProxyHeader when _httpContextAccessor?.HttpContext != null:
                var headers = _httpContextAccessor.HttpContext.Request.Headers;
                var username = headers[Settings.ProxyUserHeader].FirstOrDefault();
                if (!string.IsNullOrEmpty(username))
                {
                    return new GramUser
                    {
                        Id = username,
                        Name = headers[Settings.ProxyNameHeader].FirstOrDefault() ?? username,
                        Email = headers[Settings.ProxyEmailHeader].FirstOrDefault(),
                        IsAuthenticated = true,
                        Roles = ["user"]
                    };
                }
                return new GramUser { IsAuthenticated = false };

            default:
                // BetterAuth / Oidc unauthenticated by default until session is restored
                return new GramUser { IsAuthenticated = false };
        }
    }

    private async Task TryRestoreSessionAsync()
    {
        if (Settings.Provider != AuthProviderType.BetterAuth) return;

        try
        {
            if (File.Exists(_sessionTokenFilePath))
            {
                var json = await File.ReadAllTextAsync(_sessionTokenFilePath);
                var tokenData = JsonNode.Parse(json);
                var token = tokenData?["token"]?.ToString();
                if (!string.IsNullOrWhiteSpace(token))
                {
                    await ValidateBetterAuthSessionAsync(token);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[AuthService] Error restoring session: {ex.Message}");
        }
    }

    private async Task SaveSessionTokenAsync(string? token, GramUser? user = null)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(token))
            {
                if (File.Exists(_sessionTokenFilePath)) File.Delete(_sessionTokenFilePath);
            }
            else
            {
                var payload = new JsonObject
                {
                    ["token"] = token,
                    ["userId"] = user?.Id ?? "",
                    ["savedAt"] = DateTimeOffset.UtcNow.ToString("o")
                };
                await File.WriteAllTextAsync(_sessionTokenFilePath, payload.ToJsonString());
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[AuthService] Error persisting session token: {ex.Message}");
        }
    }

    public Task<GramUser> GetCurrentUserAsync()
    {
        return Task.FromResult(_currentUser);
    }

    public async Task<AuthResult> SignInWithEmailAsync(string email, string password)
    {
        if (Settings.Provider != AuthProviderType.BetterAuth)
        {
            // In Local/No Auth mode, instant login as requested email
            _currentUser = new GramUser
            {
                Id = email,
                Name = email.Split('@').FirstOrDefault() ?? email,
                Email = email,
                IsAuthenticated = true,
                Roles = ["admin"]
            };
            OnAuthStateChanged?.Invoke();
            return new AuthResult { Success = true, User = _currentUser };
        }

        try
        {
            var client = _httpClientFactory.CreateClient();
            var endpoint = $"{Settings.BetterAuthUrl.TrimEnd('/')}/api/auth/sign-in/email";

            var payload = new JsonObject
            {
                ["email"] = email,
                ["password"] = password
            };

            using var req = new HttpRequestMessage(HttpMethod.Post, endpoint);
            req.Content = new StringContent(payload.ToJsonString(), Encoding.UTF8, "application/json");

            var res = await client.SendAsync(req);
            var json = await res.Content.ReadAsStringAsync();

            if (res.IsSuccessStatusCode)
            {
                var sessionRes = JsonSerializer.Deserialize<BetterAuthSessionResponse>(json, new JsonSerializerOptions
                {
                    PropertyNameCaseInsensitive = true
                });

                var user = sessionRes?.User;
                var token = sessionRes?.Session?.Token;

                if (user != null)
                {
                    _currentUser = new GramUser
                    {
                        Id = user.Id,
                        Name = user.Name ?? user.Email ?? email,
                        Email = user.Email ?? email,
                        Image = user.Image,
                        IsAuthenticated = true,
                        Roles = [user.Role ?? "user"],
                        SessionToken = token
                    };

                    await SaveSessionTokenAsync(token, _currentUser);
                    OnAuthStateChanged?.Invoke();
                    return new AuthResult { Success = true, User = _currentUser, Token = token };
                }
            }

            var errNode = JsonNode.Parse(json);
            var message = errNode?["message"]?.ToString() ?? errNode?["error"]?.ToString() ?? "Invalid email or password.";
            return new AuthResult { Success = false, ErrorMessage = message };
        }
        catch (Exception ex)
        {
            return new AuthResult { Success = false, ErrorMessage = $"Could not connect to Better Auth server ({Settings.BetterAuthUrl}): {ex.Message}" };
        }
    }

    public async Task<AuthResult> SignUpWithEmailAsync(string name, string email, string password)
    {
        if (Settings.Provider != AuthProviderType.BetterAuth)
        {
            _currentUser = new GramUser
            {
                Id = email,
                Name = string.IsNullOrWhiteSpace(name) ? email.Split('@')[0] : name,
                Email = email,
                IsAuthenticated = true,
                Roles = ["admin"]
            };
            OnAuthStateChanged?.Invoke();
            return new AuthResult { Success = true, User = _currentUser };
        }

        try
        {
            var client = _httpClientFactory.CreateClient();
            var endpoint = $"{Settings.BetterAuthUrl.TrimEnd('/')}/api/auth/sign-up/email";

            var payload = new JsonObject
            {
                ["name"] = name,
                ["email"] = email,
                ["password"] = password
            };

            using var req = new HttpRequestMessage(HttpMethod.Post, endpoint);
            req.Content = new StringContent(payload.ToJsonString(), Encoding.UTF8, "application/json");

            var res = await client.SendAsync(req);
            var json = await res.Content.ReadAsStringAsync();

            if (res.IsSuccessStatusCode)
            {
                var sessionRes = JsonSerializer.Deserialize<BetterAuthSessionResponse>(json, new JsonSerializerOptions
                {
                    PropertyNameCaseInsensitive = true
                });

                var user = sessionRes?.User;
                var token = sessionRes?.Session?.Token;

                if (user != null)
                {
                    _currentUser = new GramUser
                    {
                        Id = user.Id,
                        Name = user.Name ?? name,
                        Email = user.Email ?? email,
                        Image = user.Image,
                        IsAuthenticated = true,
                        Roles = [user.Role ?? "user"],
                        SessionToken = token
                    };

                    await SaveSessionTokenAsync(token, _currentUser);
                    OnAuthStateChanged?.Invoke();
                    return new AuthResult { Success = true, User = _currentUser, Token = token };
                }
            }

            var errNode = JsonNode.Parse(json);
            var message = errNode?["message"]?.ToString() ?? errNode?["error"]?.ToString() ?? "Registration failed.";
            return new AuthResult { Success = false, ErrorMessage = message };
        }
        catch (Exception ex)
        {
            return new AuthResult { Success = false, ErrorMessage = $"Could not connect to Better Auth server ({Settings.BetterAuthUrl}): {ex.Message}" };
        }
    }

    public async Task<bool> ValidateBetterAuthSessionAsync(string sessionToken)
    {
        if (string.IsNullOrWhiteSpace(sessionToken))
        {
            _currentUser = new GramUser { IsAuthenticated = false };
            OnAuthStateChanged?.Invoke();
            return false;
        }

        try
        {
            var client = _httpClientFactory.CreateClient();
            var request = new HttpRequestMessage(HttpMethod.Get, $"{Settings.BetterAuthUrl.TrimEnd('/')}/api/auth/get-session");
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", sessionToken);
            request.Headers.Add("Cookie", $"better-auth.session_token={sessionToken}");

            var response = await client.SendAsync(request);
            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadAsStringAsync();
                var sessionResponse = JsonSerializer.Deserialize<BetterAuthSessionResponse>(json, new JsonSerializerOptions
                {
                    PropertyNameCaseInsensitive = true
                });

                if (sessionResponse?.User != null)
                {
                    _currentUser = new GramUser
                    {
                        Id = sessionResponse.User.Id,
                        Name = sessionResponse.User.Name ?? sessionResponse.User.Email ?? "User",
                        Email = sessionResponse.User.Email,
                        Image = sessionResponse.User.Image,
                        IsAuthenticated = true,
                        Roles = [sessionResponse.User.Role ?? "user"],
                        SessionToken = sessionToken
                    };
                    OnAuthStateChanged?.Invoke();
                    return true;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[AuthService] Session validation error: {ex.Message}");
        }

        _currentUser = new GramUser { IsAuthenticated = false };
        await SaveSessionTokenAsync(null);
        OnAuthStateChanged?.Invoke();
        return false;
    }

    public string GetSocialLoginUrl(string provider, string callbackUrl)
    {
        var baseAuth = Settings.BetterAuthUrl.TrimEnd('/');
        var encodedCallback = Uri.EscapeDataString(callbackUrl);
        return $"{baseAuth}/api/auth/sign-in/social?provider={provider.ToLowerInvariant()}&callbackURL={encodedCallback}";
    }

    public async Task LogoutAsync()
    {
        if (Settings.Provider == AuthProviderType.BetterAuth && !string.IsNullOrWhiteSpace(_currentUser.SessionToken))
        {
            try
            {
                var client = _httpClientFactory.CreateClient();
                var req = new HttpRequestMessage(HttpMethod.Post, $"{Settings.BetterAuthUrl.TrimEnd('/')}/api/auth/sign-out");
                req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _currentUser.SessionToken);
                await client.SendAsync(req);
            }
            catch {}
        }

        await SaveSessionTokenAsync(null);
        _currentUser = Settings.Provider == AuthProviderType.None
            ? new GramUser { Id = "local-admin", Name = "Local Admin", IsAuthenticated = true, Roles = ["admin"] }
            : new GramUser { IsAuthenticated = false };

        OnAuthStateChanged?.Invoke();
    }

    public async Task SetAuthProviderAsync(AuthProviderType provider, string? betterAuthUrl = null)
    {
        Settings.Provider = provider;
        if (!string.IsNullOrWhiteSpace(betterAuthUrl))
        {
            Settings.BetterAuthUrl = betterAuthUrl.Trim();
        }

        _currentUser = InitializeUser();
        if (provider == AuthProviderType.BetterAuth)
        {
            await TryRestoreSessionAsync();
        }

        OnAuthStateChanged?.Invoke();
    }
}

public sealed class GramAuthStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly IAuthService _authService;

    public GramAuthStateProvider(IAuthService authService)
    {
        _authService = authService;
        _authService.OnAuthStateChanged += NotifyStateChanged;
    }

    public override async Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var user = await _authService.GetCurrentUserAsync();
        return new AuthenticationState(user.ToClaimsPrincipal());
    }

    private void NotifyStateChanged()
    {
        NotifyAuthenticationStateChanged(GetAuthenticationStateAsync());
    }

    public void Dispose()
    {
        _authService.OnAuthStateChanged -= NotifyStateChanged;
    }
}

@namespace Gram.Blazor.Components
@using Gram.Blazor.Shared
@using Gram.Blazor.Components.ShadCn
@inject IAuthService AuthService
@inject ISonnerService SonnerService
@inject NavigationManager NavManager

@if (IsOpen)
{
    <div class="modal-backdrop" @onclick="Close">
        <div class="modal-dialog auth-modal-dialog" style="max-width: 420px; border-radius: var(--radius-lg);" @onclick:stopPropagation="true">
            <div class="modal-header" style="border-bottom: none; padding-bottom: 0;">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <span style="font-size: 18px;">🔐</span>
                    <span class="modal-title" style="font-size: 16px; font-weight: 600;">
                        @(isSignUpTab ? "Create Gram Account" : "Sign in to Gram")
                    </span>
                </div>
                <button class="btn-close-modal" @onclick="Close" title="Close">✕</button>
            </div>

            <div class="modal-body" style="padding: 16px 20px; display: flex; flex-direction: column; gap: 14px;">
                <!-- Tab Switcher -->
                <div style="display: flex; background: var(--bg-hover); padding: 3px; border-radius: var(--radius-sm); gap: 2px;">
                    <button type="button"
                            class="auth-tab-btn @(!isSignUpTab ? "active" : "")"
                            style="flex: 1; padding: 6px 12px; font-size: 12.5px; font-weight: 500; border: none; border-radius: calc(var(--radius-sm) - 2px); background: @(!isSignUpTab ? "var(--bg-panel)" : "transparent"); color: var(--text-primary); cursor: pointer; transition: all 0.12s ease;"
                            @onclick="() => { isSignUpTab = false; errorMessage = null; }">
                        Sign In
                    </button>
                    <button type="button"
                            class="auth-tab-btn @(isSignUpTab ? "active" : "")"
                            style="flex: 1; padding: 6px 12px; font-size: 12.5px; font-weight: 500; border: none; border-radius: calc(var(--radius-sm) - 2px); background: @(isSignUpTab ? "var(--bg-panel)" : "transparent"); color: var(--text-primary); cursor: pointer; transition: all 0.12s ease;"
                            @onclick="() => { isSignUpTab = true; errorMessage = null; }">
                        Create Account
                    </button>
                </div>

                @if (!string.IsNullOrWhiteSpace(errorMessage))
                {
                    <Alert Variant="destructive">
                        <AlertTitle>Authentication Error</AlertTitle>
                        <AlertDescription>@errorMessage</AlertDescription>
                    </Alert>
                }

                @if (AuthService.Settings.Provider == AuthProviderType.BetterAuth)
                {
                    <!-- Social Login Providers -->
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
                        <Button Variant="outline" Size="sm" Class="w-full" OnClick='() => LoginWithSocial("github")'>
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path>
                            </svg>
                            <span>GitHub</span>
                        </Button>
                        <Button Variant="outline" Size="sm" Class="w-full" OnClick='() => LoginWithSocial("google")'>
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <circle cx="12" cy="12" r="10"></circle>
                                <path d="M12 8v8m-4-4h8"></path>
                            </svg>
                            <span>Google</span>
                        </Button>
                    </div>

                    <div style="display: flex; align-items: center; gap: 10px; margin: 2px 0;">
                        <div style="flex: 1; height: 1px; background: var(--border-color);"></div>
                        <span style="font-size: 11px; color: var(--text-muted); text-transform: uppercase;">or continue with email</span>
                        <div style="flex: 1; height: 1px; background: var(--border-color);"></div>
                    </div>
                }

                <form @onsubmit="HandleSubmit" style="display: flex; flex-direction: column; gap: 12px;">
                    @if (isSignUpTab)
                    {
                        <div class="sheet-field">
                            <label class="sheet-label">Full Name</label>
                            <Input @bind-Value="nameInput" Placeholder="Ada Lovelace" Disabled="@isLoading" />
                        </div>
                    }

                    <div class="sheet-field">
                        <label class="sheet-label">Email Address</label>
                        <Input @bind-Value="emailInput" Type="email" Placeholder="user@example.com" Disabled="@isLoading" />
                    </div>

                    <div class="sheet-field">
                        <label class="sheet-label">Password</label>
                        <Input @bind-Value="passwordInput" Type="password" Placeholder="••••••••••••" Disabled="@isLoading" />
                    </div>

                    <Button Variant="default" Size="default" Class="w-full" Type="submit" Disabled="@isLoading" Style="margin-top: 6px;">
                        @if (isLoading)
                        {
                            <span>Processing...</span>
                        }
                        else
                        {
                            <span>@(isSignUpTab ? "Create Account" : "Sign In")</span>
                        }
                    </Button>
                </form>
            </div>

            <div class="modal-footer" style="background: var(--bg-panel-subtle); border-top: 1px solid var(--border-color); padding: 10px 16px; border-bottom-left-radius: var(--radius-lg); border-bottom-right-radius: var(--radius-lg); text-align: center;">
                <span style="font-size: 11.5px; color: var(--text-muted);">
                    Protected by <strong>Better Auth</strong> & Gram End-to-End Encryption
                </span>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsOpen { get; set; }
    [Parameter] public EventCallback<bool> IsOpenChanged { get; set; }
    [Parameter] public EventCallback OnSuccess { get; set; }

    private bool isSignUpTab = false;
    private string nameInput = "";
    private string emailInput = "";
    private string passwordInput = "";
    private string? errorMessage = null;
    private bool isLoading = false;

    private async Task Close()
    {
        IsOpen = false;
        await IsOpenChanged.InvokeAsync(false);
    }

    private void LoginWithSocial(string provider)
    {
        var callback = NavManager.Uri;
        var url = AuthService.GetSocialLoginUrl(provider, callback);
        NavManager.NavigateTo(url, forceLoad: true);
    }

    private async Task HandleSubmit()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(emailInput))
        {
            errorMessage = "Please enter your email address.";
            return;
        }

        if (string.IsNullOrWhiteSpace(passwordInput) && AuthService.Settings.Provider == AuthProviderType.BetterAuth)
        {
            errorMessage = "Please enter your password.";
            return;
        }

        isLoading = true;
        StateHasChanged();

        try
        {
            AuthResult result;
            if (isSignUpTab)
            {
                result = await AuthService.SignUpWithEmailAsync(nameInput, emailInput, passwordInput);
            }
            else
            {
                result = await AuthService.SignInWithEmailAsync(emailInput, passwordInput);
            }

            if (result.Success)
            {
                SonnerService.Success("Welcome to Gram", $"Signed in as {result.User?.Name}");
                await Close();
                await OnSuccess.InvokeAsync();
            }
            else
            {
                errorMessage = result.ErrorMessage ?? "Authentication failed.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }
}

