.about-tagline {
  margin: 4px 0 0 0;
  font-size: 12.5px;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* Tool Call Cards */
.tool-call-card {
  margin: 6px 0;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all 0.15s ease;
}

.tool-call-card.running {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px rgba(var(--accent-rgb, 99, 102, 241), 0.15);
}

.tool-call-card.error {
  border-color: var(--danger, #ef4444);
}

.tool-call-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  cursor: pointer;
  background: var(--bg-panel-subtle);
  user-select: none;
}

.tool-call-header:hover {
  background: var(--bg-hover);
}

.tool-call-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.tool-call-icon {
  font-size: 14px;
}

.tool-call-name {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.tool-call-args-preview {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 280px;
}

.tool-call-status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-status-badge {
  font-size: 10.5px;
  font-weight: 500;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 4px;
}

.tool-status-badge.running {
  background: rgba(var(--accent-rgb, 99, 102, 241), 0.15);
  color: var(--accent);
}

.tool-status-badge.success {
  background: rgba(34, 197, 94, 0.12);
  color: #22c55e;
}

.tool-status-badge.error {
  background: rgba(239, 68, 68, 0.12);
  color: #ef4444;
}

.spinner-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  animation: pulseDot 1s infinite alternate ease-in-out;
}

@keyframes pulseDot {
  0% { transform: scale(0.6); opacity: 0.4; }
  100% { transform: scale(1.1); opacity: 1; }
}

.tool-chevron {
  transition: transform 0.15s ease;
  color: var(--text-muted);
}

.tool-chevron.expanded {
  transform: rotate(180deg);
}

.tool-call-body {
  padding: 10px 12px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-panel);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tool-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-section-label {
  font-size: 10.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
}

.tool-code-block {
  margin: 0;
  padding: 8px 10px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-all;
  color: var(--text-primary);
  max-height: 240px;
}

.tool-code-block.error-output {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.06);
}

