/* Topbar Tabs & Divider */
.topbar-tabs-container {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: 6px;
}

.topbar-divider {
  width: 1px;
  height: 18px;
  background: var(--border-color);
  margin: 0 4px;
}

.topbar-tabs-list {
  display: flex;
  align-items: center;
  gap: 4px;
  max-width: 460px;
  overflow-x: auto;
}

.topbar-tab {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.12s ease;
  user-select: none;
  max-width: 140px;
  white-space: nowrap;
}

.topbar-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.topbar-tab.active {
  background: var(--bg-panel);
  color: var(--text-primary);
  border-color: var(--border-color);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

.topbar-tab-icon {
  font-size: 12px;
}

.topbar-tab-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topbar-tab-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 10px;
  padding: 1px 3px;
  border-radius: 2px;
  cursor: pointer;
  opacity: 0.6;
}

.topbar-tab-close:hover {
  opacity: 1;
  background: rgba(255, 255, 255, 0.1);
  color: var(--danger);
}

.btn-new-tab {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  width: 24px;
  height: 24px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.btn-new-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-color);
}

.topbar-toolbox-action {
  display: flex;
  align-items: center;
}

.btn-toolbox-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--bg-panel-subtle);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.12s ease;
}

.btn-toolbox-toggle:hover {
  background: var(--bg-hover);
  border-color: var(--accent);
}

.btn-toolbox-toggle.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.toolbox-badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-muted);
}

.toolbox-badge-dot.connected {
  background: #22c55e;
  box-shadow: 0 0 6px rgba(34, 197, 94, 0.5);
}

