@code {
    private bool isEditingTitle = false;
    private string editingTitleDraft = "";
    private ElementReference titleInputRef;

    private bool showAuthModal = false;
    private bool showUserDropdown = false;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
        ChatStateService.OnChange += StateHasChanged;
        SettingsService.OnBreadcrumbChanged += StateHasChanged;
        AuthService.OnAuthStateChanged += StateHasChanged;
    }

    private async Task HandleLogout()
    {
        showUserDropdown = false;
        await AuthService.LogoutAsync();
        SonnerService.Info("Signed out", "You have been signed out.");
    }

    private async Task StartEditingTitle()
    {
        editingTitleDraft = ChatStateService.ActiveChatTitle;
        isEditingTitle = true;
        await Task.Yield();
        try
        {
            await titleInputRef.FocusAsync();
        }
        catch {}
    }

    private async Task CommitTitleChange()
    {
        if (!isEditingTitle) return;
        isEditingTitle = false;
        var cleanTitle = string.IsNullOrWhiteSpace(editingTitleDraft) ? "New chat" : editingTitleDraft.Trim();
        if (cleanTitle != ChatStateService.ActiveChatTitle)
        {
            await ChatStateService.RenameActiveChatAsync(cleanTitle);
        }
    }

    private async Task HandleTitleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await CommitTitleChange();
        }
        else if (e.Key == "Escape")
        {
            isEditingTitle = false;
        }
    }

    private bool IsActive(string path)

