protected override void OnInitialized()
{
    dotNetHelper = DotNetObjectReference.Create(this);
    ConversationService.OnChange += OnConversationsChanged;
    ChatStateService.OnTitleRenamed += OnExternalTitleRenamed;
    TabService.OnTabsChanged += OnTabsUpdated;

    if (TabService.ActiveTab?.Type == WorkspaceTabType.Chat && !string.IsNullOrWhiteSpace(TabService.ActiveTab.ChatId))
    {
        activeId = TabService.ActiveTab.ChatId;
    }
    else
    {
        activeId = conversations.FirstOrDefault()?.Id ?? "default";
        TabService.OpenChatTab(activeId, Active.Title);
    }

    var fav = ModelService.Models.FirstOrDefault(m => m.IsFavorite);
    activeModelId = fav?.Id ?? ModelService.Models.FirstOrDefault()?.Id ?? "";
    ChatStateService.ActiveChatTitle = Active.Title;
}

private void OnTabsUpdated()
{
    if (TabService.ActiveTab?.Type == WorkspaceTabType.Chat && !string.IsNullOrWhiteSpace(TabService.ActiveTab.ChatId))
    {
        if (activeId != TabService.ActiveTab.ChatId)
        {
            activeId = TabService.ActiveTab.ChatId;
            ChatStateService.ActiveChatTitle = Active.Title;
            InvokeAsync(StateHasChanged);
        }
    }
}

private async Task OnExternalTitleRenamed(string newTitle)
{
    Active.Title = newTitle;
    TabService.UpdateChatTabTitle(Active.Id, newTitle);
    await ConversationService.SaveConversationAsync(Active);
    SonnerService.Success("Chat renamed", $"Title updated to: {newTitle}");
    await InvokeAsync(StateHasChanged);
}

private void OnConversationsChanged()
{
    InvokeAsync(StateHasChanged);
}

private async Task OnTitleChanged()
{
    ChatStateService.ActiveChatTitle = Active.Title;
    TabService.UpdateChatTabTitle(Active.Id, Active.Title);
    await ConversationService.SaveConversationAsync(Active);
}

private void NewConversation()
{
    var id = Guid.NewGuid().ToString("N")[..8];
    activeId = id;
    TabService.OpenChatTab(id, "New chat");
    ChatStateService.ActiveChatTitle = "New chat";
    StateHasChanged();
}

private void SelectConversation(string id)
{
    activeId = id;
    var chat = conversations.FirstOrDefault(c => c.Id == id);
    TabService.OpenChatTab(id, chat?.Title ?? "New chat");
    ChatStateService.ActiveChatTitle = Active.Title;
}

