@page "/login"
@page "/signin"
@rendermode InteractiveServer
@using Gram.Blazor.Shared
@using Gram.Blazor.Components.ShadCn
@inject IAuthService AuthService
@inject ISonnerService SonnerService
@inject NavigationManager NavManager

<PageTitle>Sign In · Gram</PageTitle>

<div class="login-container" style="min-height: 80vh; display: flex; align-items: center; justify-content: center; padding: 24px;">
    <div class="login-card" style="width: 100%; max-width: 380px; background: var(--bg-panel); border: 1px solid var(--border-color); border-radius: var(--radius-lg); padding: 32px; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); display: flex; flex-direction: column; gap: 20px;">

        <!-- Header / Logo -->
        <div style="display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px;">
            <a href="/" style="font-size: 24px; font-weight: 700; color: var(--text-primary); text-decoration: none; letter-spacing: -0.03em;">
                Gram
            </a>
            <p style="font-size: 13px; color: var(--text-muted); margin: 0;">
                @(isSignUpMode ? "Create a new local or cloud account" : "Enter your credentials to continue")
            </p>
        </div>

        <!-- Mode Toggle Switch -->
        <div style="display: flex; background: var(--bg-hover); padding: 3px; border-radius: var(--radius-sm); gap: 2px;">
            <button type="button"
                    class="auth-tab-btn"
                    style="flex: 1; padding: 6px 12px; font-size: 12px; font-weight: 500; border: none; border-radius: calc(var(--radius-sm) - 2px); background: @(!isSignUpMode ? "var(--bg-panel)" : "transparent"); color: var(--text-primary); cursor: pointer; transition: all 0.12s ease;"
                    @onclick="() => { isSignUpMode = false; errorMessage = null; }">
                Sign In
            </button>
            <button type="button"
                    class="auth-tab-btn"
                    style="flex: 1; padding: 6px 12px; font-size: 12px; font-weight: 500; border: none; border-radius: calc(var(--radius-sm) - 2px); background: @(isSignUpMode ? "var(--bg-panel)" : "transparent"); color: var(--text-primary); cursor: pointer; transition: all 0.12s ease;"
                    @onclick="() => { isSignUpMode = true; errorMessage = null; }">
                Sign Up
            </button>
        </div>

        @if (!string.IsNullOrWhiteSpace(errorMessage))
        {
            <div style="padding: 10px 12px; font-size: 12px; border-radius: var(--radius-sm); background: rgba(239, 68, 68, 0.08); border: 1px solid rgba(239, 68, 68, 0.2); color: #ef4444;">
                @errorMessage
            </div>
        }

        <!-- Form -->
        <form @onsubmit="HandleSubmit" style="display: flex; flex-direction: column; gap: 14px;">
            @if (isSignUpMode)
            {
                <div class="sheet-field">
                    <label class="sheet-label">Full Name</label>
                    <input type="text" 
                           class="sheet-input" 
                           @bind="nameInput" 
                           placeholder="Ada Lovelace" 
                           disabled="@isLoading" />
                </div>
            }

            <div class="sheet-field">
                <label class="sheet-label">Email Address</label>
                <input type="email" 
                       class="sheet-input" 
                       @bind="emailInput" 
                       placeholder="admin@gram.local" 
                       required 
                       disabled="@isLoading" />
            </div>

            <div class="sheet-field">
                <div style="display: flex; align-items: center; justify-content: space-between;">
                    <label class="sheet-label">Password</label>
                </div>
                <input type="password" 
                       class="sheet-input" 
                       @bind="passwordInput" 
                       placeholder="••••••••••••" 
                       required 
                       disabled="@isLoading" />
            </div>

            <Button Variant="default" 
                    Size="default" 
                    Class="w-full" 
                    Type="submit" 
                    Disabled="@isLoading" 
                    Style="margin-top: 4px;">
                @if (isLoading)
                {
                    <span>Authenticating...</span>
                }
                else
                {
                    <span>@(isSignUpMode ? "Create Account" : "Sign In")</span>
                }
            </Button>
        </form>

        <!-- Footer / Default credentials reminder -->
        <div style="border-top: 1px solid var(--border-color); padding-top: 14px; text-align: center;">
            <p style="font-size: 11.5px; color: var(--text-muted); margin: 0; line-height: 1.4;">
                Default SQLite Admin:<br/>
                <code style="font-family: var(--font-mono); color: var(--text-secondary);">admin@gram.local</code> / <code style="font-family: var(--font-mono); color: var(--text-secondary);">admin123</code>
            </p>
        </div>
    </div>
</div>

@code {
    private bool isSignUpMode = false;
    private bool isLoading = false;
    private string nameInput = "";
    private string emailInput = "admin@gram.local";
    private string passwordInput = "";
    private string? errorMessage;

    [SupplyParameterFromQuery(Name = "returnUrl")]
    public string? ReturnUrl { get; set; }

    private async Task HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(emailInput) || string.IsNullOrWhiteSpace(passwordInput))
        {
            errorMessage = "Please provide both an email and password.";
            return;
        }

        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            AuthResult result;
            if (isSignUpMode)
            {
                result = await AuthService.SignUpWithEmailAsync(nameInput, emailInput, passwordInput);
            }
            else
            {
                result = await AuthService.SignInWithEmailAsync(emailInput, passwordInput);
            }

            if (result.Success)
            {
                SonnerService.Success("Welcome back", $"Signed in as {result.User?.Name ?? emailInput}");
                var redirectTarget = !string.IsNullOrWhiteSpace(ReturnUrl) ? ReturnUrl : "/";
                NavManager.NavigateTo(redirectTarget);
            }
            else
            {
                errorMessage = result.ErrorMessage ?? "Authentication failed.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error during authentication: {ex.Message}";
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }
}

