@page "/login"
@page "/signin"
@rendermode InteractiveServer
@using Gram.Blazor.Shared
@using Gram.Blazor.Components.ShadCn
@inject IAuthService AuthService
@inject ISonnerService SonnerService
@inject NavigationManager NavManager

<PageTitle>Sign In · Gram</PageTitle>

<div class="remote-auth-wrapper">
    <!-- Left Column: Authentication Form -->
    <div class="remote-auth-form-column">
        <div class="remote-auth-form-container">

            <!-- App Logo Badge -->
            <div class="remote-logo-badge">
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
                    <path d="M7 4h10a4 4 0 0 1 4 4v0a4 4 0 0 1-4 4H7V4z" fill="#2563eb" />
                    <path d="M7 12h7a4 4 0 0 1 4 4v0a4 4 0 0 1-4 4H7V12z" fill="#3b82f6" opacity="0.9" />
                    <path d="M7 4v16" stroke="#1d4ed8" stroke-width="2.5" stroke-linecap="round" />
                </svg>
            </div>

            <!-- Header Titles -->
            <div class="remote-auth-header">
                <h1 class="remote-auth-title">
                    @(isSignUpMode ? "Create your account" : "Welcome back!")
                </h1>
                <div class="remote-auth-subtitle">
                    @if (isSignUpMode)
                    {
                        <span>Already have an account?</span>
                        <button type="button" class="remote-link-btn" @onclick="() => { isSignUpMode = false; errorMessage = null; }">
                            Sign in
                        </button>
                    }
                    else
                    {
                        <span>Don't have an account yet?</span>
                        <button type="button" class="remote-link-btn" @onclick="() => { isSignUpMode = true; errorMessage = null; }">
                            Sign up now
                        </button>
                    }
                </div>
            </div>

            @if (!string.IsNullOrWhiteSpace(errorMessage))
            {
                <div class="remote-auth-error">
                    @errorMessage
                </div>
            }

            <!-- Form -->
            <form @onsubmit="HandleSubmit" class="remote-form">
                @if (isSignUpMode)
                {
                    <div class="remote-input-wrapper">
                        <input type="text"
                               class="remote-input"
                               @bind="nameInput"
                               placeholder="Full name"
                               disabled="@isLoading" />
                    </div>
                }

                <div class="remote-input-wrapper">
                    <input type="email"
                           class="remote-input"
                           @bind="emailInput"
                           placeholder="Email address"
                           required
                           disabled="@isLoading" />
                </div>

                <div class="remote-input-wrapper with-icon">
                    <input type="@(showPassword ? "text" : "password")"
                           class="remote-input"
                           @bind="passwordInput"
                           placeholder="Password"
                           required
                           disabled="@isLoading" />

                    <button type="button" class="remote-input-toggle-btn" @onclick="() => showPassword = !showPassword" tabindex="-1" title="Toggle password visibility">
                        @if (showPassword)
                        {
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                                <line x1="1" y1="1" x2="23" y2="23"></line>
                            </svg>
                        }
                        else
                        {
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                <circle cx="12" cy="12" r="3"></circle>
                            </svg>
                        }
                    </button>
                </div>

                <!-- Remember Me & Forgot Password Row -->
                <div class="remote-form-options">
                    <label class="remote-checkbox-label">
                        <input type="checkbox" class="remote-checkbox" @bind="rememberMe" />
                        <span>Remember me</span>
                    </label>

                    @if (!isSignUpMode)
                    {
                        <a href="javascript:void(0)" class="remote-link-btn text-sm" @onclick="() => SonnerService.Info("Password reset", "Default SQLite credentials: admin@gram.local / admin123")">
                            Forgot password?
                        </a>
                    }
                </div>

                <!-- Main Action Button -->
                <button type="submit" class="remote-primary-btn" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span>Authenticating...</span>
                    }
                    else
                    {
                        <span>@(isSignUpMode ? "Create account" : "Log in")</span>
                    }
                </button>
            </form>

            <!-- OR Divider -->
            <div class="remote-or-divider">
                <span class="remote-or-line"></span>
                <span class="remote-or-text">OR</span>
                <span class="remote-or-line"></span>
            </div>

            <!-- SSO / Quick Admin Login -->
            <div class="remote-sso-section">
                <button type="button" class="remote-sso-btn" @onclick="FillAdminCredentials">
                    Log in with Default Admin
                </button>
            </div>

        </div>
    </div>

    <!-- Right Column: Geometric Hero Artwork Banner -->
    <div class="remote-artwork-column">
        <div class="geometric-pattern-grid">
            @for (int row = 0; row < 5; row++)
            {
                <div class="geometric-row">
                    @for (int col = 0; col < 3; col++)
                    {
                        <div class="geometric-quadrant">
                            <div class="geometric-curve"></div>
                        </div>
                    }
                </div>
            }
        </div>
    </div>
</div>

<!-- Bottom Minimal Footer Bar -->
<footer class="remote-footer-bar">
    <div class="remote-footer-brand">
        <div class="remote-footer-logo-dot">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <path d="M7 4h10a4 4 0 0 1 4 4v0a4 4 0 0 1-4 4H7V4z" fill="#fff" />
                <path d="M7 12h7a4 4 0 0 1 4 4v0a4 4 0 0 1-4 4H7V12z" fill="#fff" opacity="0.8" />
            </svg>
        </div>
        <span>Gram</span>
    </div>

    <div class="remote-footer-meta">
        <span>SQLite Embedded Database</span>
    </div>
</footer>

@code {
    private bool isSignUpMode = false;
    private bool isLoading = false;
    private bool showPassword = false;
    private bool rememberMe = true;

    private string nameInput = "";
    private string emailInput = "admin@gram.local";
    private string passwordInput = "";
    private string? errorMessage;

    [SupplyParameterFromQuery(Name = "returnUrl")]
    public string? ReturnUrl { get; set; }

