@page "/login"
@page "/signin"
@rendermode InteractiveServer
@using Gram.Blazor.Shared
@using Gram.Blazor.Components.ShadCn
@inject IAuthService AuthService
@inject ISonnerService SonnerService
@inject NavigationManager NavManager

<PageTitle>Sign In · Gram</PageTitle>

<div class="remote-auth-wrapper">
    <!-- Left Column: Authentication Form -->
    <div class="remote-auth-form-column">
        <div class="remote-auth-form-container">

            <!-- Gram Custom Minimal Logo Badge -->
            <div class="gram-auth-logo-badge">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                    <rect x="3" y="3" width="18" height="18" rx="6" fill="var(--color-primary, #6366f1)" />
                    <path d="M7 8h10M7 12h6M7 16h8" stroke="#ffffff" stroke-width="2.2" stroke-linecap="round" />
                    <circle cx="16" cy="14" r="2.2" fill="#38bdf8" />
                </svg>
            </div>

            <!-- Header Titles -->
            <div class="remote-auth-header">
                <h1 class="remote-auth-title">
                    @(isSignUpMode ? "Create your account" : "Welcome to Gram")
                </h1>
                <div class="remote-auth-subtitle">
                    @if (isSignUpMode)
                    {
                        <span>Already have an account?</span>
                        <button type="button" class="remote-link-btn" @onclick="() => { isSignUpMode = false; errorMessage = null; }">
                            Sign in
                        </button>
                    }
                    else
                    {
                        <span>Don't have an account yet?</span>
                        <button type="button" class="remote-link-btn" @onclick="() => { isSignUpMode = true; errorMessage = null; }">
                            Sign up now
                        </button>
                    }
                </div>
            </div>

            @if (!string.IsNullOrWhiteSpace(errorMessage))
            {
                <div class="remote-auth-error">
                    @errorMessage
                </div>
            }

            <!-- Form -->
            <form @onsubmit="HandleSubmit" class="remote-form">
                @if (isSignUpMode)
                {
                    <div class="remote-input-wrapper">
                        <input type="text"
                               class="remote-input"
                               @bind="nameInput"
                               placeholder="Full name"
                               disabled="@isLoading" />
                    </div>
                }

                <div class="remote-input-wrapper">
                    <input type="email"
                           class="remote-input"
                           @bind="emailInput"
                           placeholder="Email address"
                           required
                           disabled="@isLoading" />
                </div>

                <div class="remote-input-wrapper with-icon">
                    <input type="@(showPassword ? "text" : "password")"
                           class="remote-input"
                           @bind="passwordInput"
                           placeholder="Password"
                           required
                           disabled="@isLoading" />

                    <button type="button" class="remote-input-toggle-btn" @onclick="() => showPassword = !showPassword" tabindex="-1" title="Toggle password visibility">
                        @if (showPassword)
                        {
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                                <line x1="1" y1="1" x2="23" y2="23"></line>
                            </svg>
                        }
                        else
                        {
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                <circle cx="12" cy="12" r="3"></circle>
                            </svg>
                        }
                    </button>
                </div>

                <!-- Remember Me & Forgot Password Row -->
                <div class="remote-form-options">
                    <label class="remote-checkbox-label">
                        <input type="checkbox" class="remote-checkbox" @bind="rememberMe" />
                        <span>Remember me</span>
                    </label>

                    @if (!isSignUpMode)
                    {
                        <a href="javascript:void(0)" class="remote-link-btn text-sm" @onclick='() => SonnerService.Info("Database User", "You can sign up for a new account or sign in with your SQLite credentials.")'>
                            Need help?
                        </a>
                    }
                </div>

                <!-- Main Action Button -->
                <button type="submit" class="remote-primary-btn" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span>Authenticating...</span>
                    }
                    else
                    {
                        <span>@(isSignUpMode ? "Create account" : "Log in")</span>
                    }
                </button>
            </form>

        </div>
    </div>

    <!-- Right Column: Unique Gram Autonomous Terminal Artwork Graphic -->
    <div class="gram-artwork-column">
        <div class="gram-artwork-glow"></div>
        <div class="gram-artwork-canvas">

            <!-- Code / Agent Floating Card -->
            <div class="gram-art-card">
                <div class="gram-art-card-header">
                    <div class="gram-art-dot red"></div>
                    <div class="gram-art-dot yellow"></div>
                    <div class="gram-art-dot green"></div>
                    <span class="gram-art-card-title">gram.orchestrator · interactive</span>
                </div>
                <div class="gram-art-code-body">
                    <div class="gram-code-line"><span class="c-kw">const</span> <span class="c-var">gram</span> = <span class="c-kw">await</span> GramEngine.<span class="c-fn">spawn</span>({</div>
                    <div class="gram-code-line ind"><span class="c-prop">sandbox</span>: <span class="c-str">"isolated-cde"</span>,</div>
                    <div class="gram-code-line ind"><span class="c-prop">autonomy</span>: <span class="c-str">"safe-approve"</span>,</div>
                    <div class="gram-code-line ind"><span class="c-prop">database</span>: <span class="c-str">"sqlite.embedded"</span></div>
                    <div class="gram-code-line">});</div>
                    <div class="gram-code-line mt"><span class="c-kw">await</span> gram.<span class="c-fn">dispatch</span>(<span class="c-str">"Build high-speed reactive UI"</span>);</div>
                    <div class="gram-code-output">
                        <span class="c-badge">ready</span>
                        <span>Multi-model workspace active</span>
                    </div>
                </div>
            </div>

            <!-- Decorative Architecture Badge Nodes -->
            <div class="gram-node-pill pill-top">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <polygon points="12 2 2 7 12 12 22 7 12 2"></polygon>
                    <polyline points="2 17 12 22 22 17"></polyline>
                    <polyline points="2 12 12 17 22 12"></polyline>
                </svg>
                <span>Toolbox & CDE Ready</span>
            </div>

            <div class="gram-node-pill pill-bottom">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#a78bfa" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path>
                </svg>
                <span>Autonomous Safeguards</span>
            </div>

        </div>
    </div>
</div>

<!-- Bottom Minimal Footer Bar -->
<footer class="remote-footer-bar">
    <div class="remote-footer-brand">
        <div class="remote-footer-logo-dot">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                <rect x="4" y="4" width="16" height="16" rx="4" fill="#ffffff" />
                <circle cx="12" cy="12" r="3" fill="#6366f1" />
            </svg>
        </div>
        <span>Gram</span>
    </div>

    <div class="remote-footer-meta">
        <span>SQLite Embedded Database</span>
    </div>
</footer>

@code {
    private bool isSignUpMode = false;
    private bool isLoading = false;
    private bool showPassword = false;
    private bool rememberMe = true;

    private string nameInput = "";
    private string emailInput = "";
    private string passwordInput = "";
    private string? errorMessage;

    [SupplyParameterFromQuery(Name = "returnUrl")]
    public string? ReturnUrl { get; set; }

    private async Task HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(emailInput) || string.IsNullOrWhiteSpace(passwordInput))
        {
            errorMessage = "Please enter your email and password.";
            return;
        }

        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            AuthResult result;
            if (isSignUpMode)
            {
                result = await AuthService.SignUpWithEmailAsync(nameInput, emailInput, passwordInput);
            }
            else
            {
                result = await AuthService.SignInWithEmailAsync(emailInput, passwordInput);
            }

            if (result.Success)
            {
                SonnerService.Success("Welcome back", $"Signed in as {result.User?.Name ?? emailInput}");
                var redirectTarget = !string.IsNullOrWhiteSpace(ReturnUrl) ? ReturnUrl : "/";
                NavManager.NavigateTo(redirectTarget);
            }
            else
            {
                errorMessage = result.ErrorMessage ?? "Invalid email or password.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Authentication error: {ex.Message}";
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }
}

