  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.05);
  overflow: hidden;
  z-index: 2;
}

.gram-art-card-header {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 10px 14px;
  background: rgba(0, 0, 0, 0.35);
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.gram-art-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}
.gram-art-dot.red { background: #ef4444; }
.gram-art-dot.yellow { background: #f59e0b; }
.gram-art-dot.green { background: #10b981; }

.gram-art-card-title {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #94a3b8;
  margin-left: 6px;
}

.gram-art-code-body {
  padding: 18px 20px;
  font-family: var(--font-mono);
  font-size: 12.5px;
  line-height: 1.7;
  color: #e2e8f0;
  text-align: left;
}

.gram-code-line {
  white-space: pre;
}

.gram-code-line.ind {
  padding-left: 16px;
}

.gram-code-line.mt {
  margin-top: 10px;
}

.c-kw { color: #f43f5e; font-weight: 600; }
.c-var { color: #38bdf8; }
.c-fn { color: #a78bfa; font-weight: 600; }
.c-prop { color: #cbd5e1; }
.c-str { color: #34d399; }

.gram-code-output {
  margin-top: 14px;
  padding: 8px 12px;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 6px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11.5px;
  color: #94a3b8;
}

.c-badge {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.3);
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.gram-node-pill {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(15, 23, 42, 0.9);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 8px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  color: #f8fafc;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  z-index: 3;
}

.pill-top {
  top: -14px;
  right: 10px;
}

.pill-bottom {
  bottom: -14px;
  left: 10px;
}

/* Bottom Footer Bar */
.remote-footer-bar {
  height: 48px;
  background: #090d16;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  color: #ffffff;
  font-size: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.remote-footer-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.remote-footer-logo-dot {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: #6366f1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.remote-footer-meta {
  color: #94a3b8;
  font-size: 11.5px;
}

@media (max-width: 860px) {
  .gram-artwork-column {
    display: none;
  }
}

