.page-frame.login-frame {
  padding: 0;
  max-width: 100%;
  height: 100vh;
  overflow: hidden;
}

.gram-auth-page-dark {
  display: flex;
  width: 100vw;
  height: 100vh;
  background: #090d16;
  color: #f8fafc;
  overflow: hidden;
}

.gram-auth-form-column {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
  background: #090d16;
  overflow-y: auto;
  z-index: 2;
}

.gram-auth-form-box {
  width: 100%;
  max-width: 360px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.gram-auth-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.gram-auth-headings {
  margin-bottom: 28px;
}

.gram-auth-heading-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #ffffff;
  margin: 0 0 8px 0;
}

.gram-auth-heading-sub {
  font-size: 13.5px;
  color: #94a3b8;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.gram-auth-text-link {
  background: transparent;
  border: none;
  color: #60a5fa;
  font-weight: 600;
  font-size: 13.5px;
  cursor: pointer;
  padding: 0;
  text-decoration: none;
  transition: color 0.12s ease;
}

.gram-auth-text-link:hover {
  color: #93c5fd;
  text-decoration: underline;
}

.gram-auth-text-link.sm {
  font-size: 12.5px;
  font-weight: 500;
}

.gram-auth-alert-error {
  width: 100%;
  padding: 10px 14px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
  border-radius: 8px;
  font-size: 12.5px;
  text-align: left;
  margin-bottom: 16px;
}

.gram-auth-form-body {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.gram-auth-field {
  position: relative;
  width: 100%;
}

.gram-auth-dark-input {
  width: 100%;
  padding: 12px 16px;
  font-size: 14px;
  color: #ffffff;
  background: #131b2e;
  border: 1px solid #1e293b;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}

.gram-auth-dark-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.gram-auth-dark-input::placeholder {
  color: #64748b;
}

.gram-auth-field.has-toggle .gram-auth-dark-input {
  padding-right: 42px;
}

.gram-auth-eye-btn {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: #64748b;
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.12s ease;
}

.gram-auth-eye-btn:hover {
  color: #cbd5e1;
}

.gram-auth-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 2px 0 6px 0;
  width: 100%;
}

.gram-auth-remember {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #94a3b8;
  cursor: pointer;
  user-select: none;
}

.gram-auth-check {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1.5px solid #334155;
  background: #131b2e;
  accent-color: #3b82f6;
  cursor: pointer;
}

.gram-auth-submit-btn {
  width: 100%;
  padding: 12px;
  border-radius: 24px;
  background: #2563eb;
  color: #ffffff;
  border: none;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.3);
}

.gram-auth-submit-btn:hover:not(:disabled) {
  background: #1d4ed8;
}

.gram-auth-submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Right Unsplash Image Column */
.gram-auth-image-column {
  flex: 1.25;
  position: relative;
  overflow: hidden;
  background: #030712;
  display: flex;
}

.gram-auth-unsplash-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.gram-auth-image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, #090d16 0%, transparent 25%, transparent 80%, rgba(9, 13, 22, 0.4) 100%);
  pointer-events: none;
  z-index: 1;
}

@media (max-width: 860px) {
  .gram-auth-image-column {
    display: none;
  }
}

