}

.gram-auth-submit-btn:hover:not(:disabled) {
  background: #7e22ce;
}

.gram-auth-submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Right Unsplash Image Column - Crisp, Sharp with subtle border separation */
.gram-auth-image-column {
  flex: 1.25;
