args.ReplacementContent:
.gram-auth-icon-wrap {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-panel-subtle, #120e1b);
  border: 1px solid var(--border-color, #241b36);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.gram-auth-headings {
  margin-bottom: 28px;
}

.gram-auth-heading-title {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--text-primary, #f3f0fa);
  margin: 0 0 8px 0;
}

.gram-auth-heading-sub {
  font-size: 13px;
  color: var(--text-secondary, #a89ec2);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.gram-auth-text-link {
  background: transparent;
  border: none;
  color: #c084fc;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  padding: 0;
  text-decoration: none;
  transition: color 0.12s ease;
}

.gram-auth-text-link:hover {
  color: #e9d5ff;
  text-decoration: underline;
}

.gram-auth-text-link.sm {
  font-size: 12px;
  font-weight: 500;
}

.gram-auth-alert-error {
  width: 100%;
  padding: 10px 14px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
  border-radius: var(--radius-sm, 4px);
  font-size: 12px;
  text-align: left;
  margin-bottom: 16px;
}

.gram-auth-form-body {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.gram-auth-field {
  position: relative;
  width: 100%;
}

.gram-auth-dark-input {
  width: 100%;
  padding: 10px 14px;
  font-size: 13.5px;
  color: var(--text-primary, #f3f0fa);
  background: var(--bg-panel, #0d0a14);
  border: 1px solid var(--border-color, #241b36);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}

.gram-auth-dark-input:focus {
  border-color: #a855f7;
  box-shadow: 0 0 0 2px rgba(168, 85, 247, 0.25);
}

.gram-auth-dark-input::placeholder {
  color: var(--text-muted, #6e6488);
}

.gram-auth-field.has-toggle .gram-auth-dark-input {
  padding-right: 40px;
}

.gram-auth-eye-btn {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: var(--text-muted, #6e6488);
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.12s ease;
}

.gram-auth-eye-btn:hover {
  color: var(--text-secondary, #a89ec2);
}

.gram-auth-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 2px 0 6px 0;
  width: 100%;
}

.gram-auth-remember {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--text-secondary, #a89ec2);
  cursor: pointer;
  user-select: none;
}

.gram-auth-check {
  width: 15px;
  height: 15px;
  border-radius: 3px;
  border: 1.5px solid var(--border-color, #241b36);
  background: var(--bg-panel, #0d0a14);
  accent-color: #9333ea;
  cursor: pointer;
}

.gram-auth-submit-btn {
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--radius-sm, 6px);
  background: #9333ea;
  color: #ffffff;
  border: none;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  box-shadow: 0 2px 8px rgba(147, 51, 234, 0.3);
}

.gram-auth-submit-btn:hover:not(:disabled) {
  background: #7e22ce;
}

.gram-auth-submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

