private void OnPermissionModeChanged(ChangeEventArgs e)
{
    if (Enum.TryParse<ExecutionPermissionMode>(e.Value?.ToString(), out var mode))
    {
        SecurityService.UpdatePermissionMode(mode);
        SonnerService.Info("Permissions updated", $"Agent execution mode: {mode}");
        StateHasChanged();
    }
}

private void ToggleSandboxSandboxing(ChangeEventArgs e)
{
    if (bool.TryParse(e.Value?.ToString(), out var enabled))
    {
        SecurityService.Settings.EnforceWorkspaceSandboxing = enabled;
        SecurityService.SaveSettings();
        SonnerService.Info("Sandbox updated", enabled ? "Workspace sandbox boundary enforced" : "Sandbox boundary disabled");
        StateHasChanged();
    }
}

