private async Task SaveAccountProfile()
{
    await AuthService.UpdateProfileAsync(authFullNameInput, authNicknameInput);
    SonnerService.Success("Profile updated", "Your account display name and nickname have been saved.");
    StateHasChanged();
}

private async Task SetupPasskey()
{
    isSettingUpPasskey = true;
    StateHasChanged();
    try
    {
        var result = await AuthService.RegisterPasskeyAsync();
        if (result.Success)
        {
            SonnerService.Success("Passkey configured", "WebAuthn / FIDO2 passkey enabled successfully.");
        }
        else
        {
            SonnerService.Error("Passkey error", result.ErrorMessage ?? "Could not configure passkey.");
        }
    }
    catch (Exception ex)
    {
        SonnerService.Error("Passkey error", ex.Message);
    }
    finally
    {
        isSettingUpPasskey = false;
        StateHasChanged();
    }
}

private async Task HandlePasswordReset()
{
    if (string.IsNullOrWhiteSpace(currentPasswordInput) || string.IsNullOrWhiteSpace(newPasswordInput))
    {
        SonnerService.Error("Incomplete form", "Please fill in both current and new password.");
        return;
    }

    if (newPasswordInput.Length < 6)
    {
        SonnerService.Error("Password too short", "New password must be at least 6 characters.");
        return;
    }

    isResettingPassword = true;
    StateHasChanged();
    try
    {
        var result = await AuthService.ResetPasswordAsync(currentPasswordInput, newPasswordInput);
        if (result.Success)
        {
            SonnerService.Success("Password updated", "Your password has been changed successfully.");
            showPasswordModal = false;
            currentPasswordInput = "";
            newPasswordInput = "";
        }
        else
        {
            SonnerService.Error("Password update failed", result.ErrorMessage ?? "Invalid current password.");
        }
    }
    catch (Exception ex)
    {
        SonnerService.Error("Password error", ex.Message);
    }
    finally
    {
        isResettingPassword = false;
        StateHasChanged();
    }
}

public void Dispose()

