public string? GetApiKey(string providerId)
{
    if (secureKeys.TryGetValue(providerId, out var key) && !string.IsNullOrWhiteSpace(key))
    {
        return key;
    }

    // Live environment fallback check
    var envKey = providerId.ToLowerInvariant() switch
    {
        "openrouter" => Environment.GetEnvironmentVariable("OPENROUTER_API_KEY", EnvironmentVariableTarget.Process)
                        ?? (OperatingSystem.IsWindows()
                            ? Environment.GetEnvironmentVariable("OPENROUTER_API_KEY", EnvironmentVariableTarget.User)
                              ?? Environment.GetEnvironmentVariable("GRAM_API_KEY", EnvironmentVariableTarget.User)
                              ?? Environment.GetEnvironmentVariable("OPENROUTER_KEY", EnvironmentVariableTarget.User)
                            : null),
        "openai" => Environment.GetEnvironmentVariable("OPENAI_API_KEY", EnvironmentVariableTarget.Process)
                    ?? (OperatingSystem.IsWindows() ? Environment.GetEnvironmentVariable("OPENAI_API_KEY", EnvironmentVariableTarget.User) : null),
        "anthropic" => Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY", EnvironmentVariableTarget.Process)
                       ?? (OperatingSystem.IsWindows() ? Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY", EnvironmentVariableTarget.User) : null),
        "google" => Environment.GetEnvironmentVariable("GEMINI_API_KEY", EnvironmentVariableTarget.Process)
                    ?? (OperatingSystem.IsWindows() ? Environment.GetEnvironmentVariable("GEMINI_API_KEY", EnvironmentVariableTarget.User) : null),
        "xai" => Environment.GetEnvironmentVariable("XAI_API_KEY", EnvironmentVariableTarget.Process)
                 ?? (OperatingSystem.IsWindows() ? Environment.GetEnvironmentVariable("XAI_API_KEY", EnvironmentVariableTarget.User) : null),
        _ => null
    };

    if (!string.IsNullOrWhiteSpace(envKey))
    {
        secureKeys[providerId] = envKey.Trim();
        return envKey.Trim();
    }

    return null;
}

