/* Animated Model Switcher Dropdown */
.model-dropdown-wrapper {
  position: relative;
  display: inline-flex;
}

.model-dropdown-trigger {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  user-select: none;
}

.model-dropdown-trigger:hover {
  background: var(--bg-hover);
  border-color: var(--border-focus);
}

.model-dropdown-trigger.open {
  background: var(--bg-hover);
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.model-trigger-name {
  max-width: 170px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}

.model-dropdown-chevron {
  color: var(--text-muted);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.model-dropdown-chevron.open {
  transform: rotate(180deg);
  color: var(--text-primary);
}

.model-dropdown-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9998;
  background: transparent;
}

@keyframes modelDropdownEntrance {
  0% {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.model-dropdown-menu {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  min-width: 250px;
  max-width: 320px;
  max-height: 380px;
  overflow-y: auto;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 5px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 2px;
  animation: modelDropdownEntrance 0.16s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.model-dropdown-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 9px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition: background-color 0.12s ease, color 0.12s ease;
  text-align: left;
  width: 100%;
}

.model-dropdown-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.model-dropdown-item.active {
  background: var(--bg-active);
  color: var(--text-primary);
  font-weight: 600;
}

.model-item-info {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.model-item-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.model-item-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.model-item-vendor {
  font-size: 10px;
  color: var(--text-muted);
}

.model-item-favorite {
  color: #f59e0b;
  font-size: 12px;
  flex-shrink: 0;
}

.model-item-check {
  color: var(--accent);
  flex-shrink: 0;
}

