args.ReplacementContent:
/* Context Mentions Popup */
.composer-box {
  position: relative;
}

.mention-popup {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 10px;
  min-width: 280px;
  max-width: 380px;
  max-height: 240px;
  overflow-y: auto;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  z-index: 9999;
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  animation: modelDropdownEntrance 0.15s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.mention-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
  width: 100%;
  text-align: left;
  transition: background-color 0.12s ease;
}

.mention-item:hover,
.mention-item.selected {
  background: var(--bg-hover);
}

.mention-item-left {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.mention-icon {
  font-size: 13px;
  flex-shrink: 0;
}

.mention-title {
  font-size: 12px;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mention-desc {
  font-size: 10.5px;
  color: var(--text-muted);
}

.mention-badge {
  font-size: 9.5px;
  padding: 2px 6px;
  border-radius: 9999px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
}

/* Chat Telemetry Card in Settings Sheet */
.telemetry-card {
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.telemetry-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.telemetry-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.telemetry-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.telemetry-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
}

.telemetry-metric-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.telemetry-metric-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.telemetry-meter-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.telemetry-meter-bar {
  height: 6px;
  background: var(--bg-hover);
  border-radius: 9999px;
  overflow: hidden;
}

.telemetry-meter-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 9999px;
  transition: width 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.telemetry-meter-legend {
  display: flex;
  justify-content: space-between;
  font-size: 10.5px;
  color: var(--text-muted);
}

