private record MentionItem(string Id, string Title, string Description, string Icon, string Category, string Insertion);

private bool showMentionPopup = false;
private List<MentionItem> allMentions = new();
private List<MentionItem> filteredMentions = new();

private int EstimateTokens(List<Message> msgs)
{
    if (msgs == null || msgs.Count == 0) return 0;
    int chars = msgs.Sum(m => m.Text.Length + (m.Thinking?.Length ?? 0));
    return Math.Max(1, chars / 4);
}

private void PopulateMentions()
{
    allMentions = new List<MentionItem>
    {
        new("git-diff", "@git:diff", "Include uncommitted git changes & status", "🌿", "Git", "@git:diff "),
        new("git-branch", "@git:branch", "Include current branch and commit log", "🔀", "Git", "@git:branch "),
        new("web-search", "@web:", "Trigger live web search query context", "🌐", "Web", "@web:"),
        new("toolbox", "@toolbox", "Include active Gram Toolbox engines & MCP tools", "🧰", "Toolbox", "@toolbox "),
        new("docs", "@docs", "Reference workspace documentation & architecture", "📚", "Workspace", "@docs ")
    };

    // Add workspace files if available
    try
    {
        var files = Directory.GetFiles(Environment.CurrentDirectory, "*.*", SearchOption.TopDirectoryOnly)
            .Where(f => !Path.GetFileName(f).StartsWith(".") && !f.Contains("bin") && !f.Contains("obj"))
            .Take(6);

        foreach (var f in files)
        {
            var name = Path.GetFileName(f);
            allMentions.Add(new MentionItem("file-" + name, $"@{name}", $"Attach workspace file ({Path.GetExtension(f)})", "📄", "File", $"@{name} "));
        }
    }
    catch {}
    filteredMentions = new List<MentionItem>(allMentions);
}

private void SelectMention(MentionItem mention)
{
    var atIndex = draft.LastIndexOf('@');
    if (atIndex >= 0)
    {
        draft = draft[..atIndex] + mention.Insertion;
    }
    else
    {
        draft += mention.Insertion;
    }
    showMentionPopup = false;
    StateHasChanged();
}

private void SelectModel(string modelId)
{
    activeModelId = modelId;
    Active.ModelId = modelId;
    isModelMenuOpen = false;
    StateHasChanged();
    _ = ConversationService.SaveConversationAsync(Active);
}

private readonly Conversation _fallbackConversation = new("default", "New chat", DateTimeOffset.UtcNow);
private Conversation Active => conversations.FirstOrDefault(x => x.Id == activeId) 
                               ?? conversations.FirstOrDefault() 
                               ?? _fallbackConversation;
private GramModel? ActiveModel => ModelService.Models.FirstOrDefault(m => m.Id == activeModelId);

