private async Task OnInputChanged(ChangeEventArgs e)
{
    draft = e.Value?.ToString() ?? "";

    // Context Mentions Detection
    var atIndex = draft.LastIndexOf('@');
    if (atIndex >= 0 && (atIndex == 0 || char.IsWhiteSpace(draft[atIndex - 1])))
    {
        var query = draft[(atIndex + 1)..];
        if (!query.Contains(' '))
        {
            if (allMentions.Count == 0) PopulateMentions();
            filteredMentions = string.IsNullOrWhiteSpace(query)
                ? new List<MentionItem>(allMentions)
                : allMentions.Where(m => m.Title.Contains(query, StringComparison.OrdinalIgnoreCase) || m.Description.Contains(query, StringComparison.OrdinalIgnoreCase)).ToList();
            showMentionPopup = filteredMentions.Count > 0;
        }
        else
        {
            showMentionPopup = false;
        }
    }
    else
    {
        showMentionPopup = false;
    }

    try
    {
        await JSRuntime.InvokeVoidAsync("gramAudio.autoResizeTextarea", textareaRef);
    }
    catch (Exception) {}
}

private async Task HandleKeyDown(KeyboardEventArgs e)
{
    if (e.Key == "Escape" && showMentionPopup)
    {
        showMentionPopup = false;
        preventEnter = false;
        return;
    }

    if (e.Key == "Enter" && !e.ShiftKey)
    {
        if (showMentionPopup && filteredMentions.Count > 0)
        {
            SelectMention(filteredMentions[0]);
            preventEnter = true;
            return;
        }

        preventEnter = true;
        await Send();
    }
    else
    {
        preventEnter = false;
    }
}

