.shadcn-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  border-radius: 9999px;
  background-color: var(--bg-hover, hsl(var(--muted)));
  user-select: none;
  border: 1px solid var(--border-color, hsl(var(--border)));
}

.shadcn-avatar-xs {
  width: 20px;
  height: 20px;
  font-size: 9px;
}

.shadcn-avatar-sm {
  width: 24px;
  height: 24px;
  font-size: 10.5px;
}

.shadcn-avatar-md {
  width: 32px;
  height: 32px;
  font-size: 12px;
}

.shadcn-avatar-lg {
  width: 40px;
  height: 40px;
  font-size: 14px;
}

.shadcn-avatar-xl {
  width: 48px;
  height: 48px;
  font-size: 16px;
}

.shadcn-avatar-image {
  aspect-ratio: 1 / 1;
  height: 100%;
  width: 100%;
  object-fit: cover;
}

.shadcn-avatar-fallback {
  display: flex;
