@foreach (var message in Active.Messages)
{
    @if (message.Role == "user")
    {
        <div class="message-entry user">
            <div class="user-message-row">
                <div class="message-body user-body">
                    @message.Text
                </div>
                <div class="user-avatar-wrap">
                    <Avatar Size="sm" Alt="@AuthService.CurrentUser.Name" Fallback="@(AuthService.CurrentUser.Name.FirstOrDefault().ToString().ToUpperInvariant())" />
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="message-entry assistant">
            <div class="message-header">
                <ModelIcon ModelId="@activeModelId" Size="14" />
                <span>Gram</span>
            </div>
            <div class="message-body assistant-body">
                @if (message.ToolCalls != null && message.ToolCalls.Count > 0)
                {
                    <div class="message-tool-calls" style="margin-bottom: 8px;">
                        @foreach (var tool in message.ToolCalls)
                        {
                            <ToolCallCard ToolCall="@tool" />
                        }
                    </div>
                }

                @if (string.IsNullOrEmpty(message.Text) && isGenerating && message == Active.Messages.LastOrDefault())
                {
                    @if (message.ToolCalls == null || message.ToolCalls.Count == 0)
                    {
                        <span class="typing-indicator" style="opacity: 0.6; font-style: italic;">Thinking...</span>
                    }
                }
                else
                {
                    <MarkdownView Content="@message.Text" />
                }

args.TargetContent:
@foreach (var message in Active.Messages)
{
    <div class="message-entry @(message.Role == "user" ? "user" : "assistant")">
        <div class="message-header">
            @if (message.Role == "user")
            {
                <div style="display: flex; align-items: center; justify-content: flex-end; width: 100%;">
                    <Avatar Size="xs" Alt="@AuthService.CurrentUser.Name" Fallback="@(AuthService.CurrentUser.Name.FirstOrDefault().ToString().ToUpperInvariant())" />
                </div>
            }
            else
            {
                <div style="display: flex; align-items: center; gap: 7px;">
                    <Avatar Size="xs" Alt="Gram" Fallback="G">
                        <ModelIcon ModelId="@activeModelId" Size="13" />
                    </Avatar>
                    <span>Gram</span>
                </div>
            }
        </div>
        <div class="message-body @(message.Role == "user" ? "user-body" : "assistant-body")">
            @if (message.ToolCalls != null && message.ToolCalls.Count > 0)
            {
                <div class="message-tool-calls" style="margin-bottom: 8px;">
                    @foreach (var tool in message.ToolCalls)
                    {
                        <ToolCallCard ToolCall="@tool" />
                    }
                </div>
            }

            @if (string.IsNullOrEmpty(message.Text) && isGenerating && message == Active.Messages.LastOrDefault())
            {
                @if (message.ToolCalls == null || message.ToolCalls.Count == 0)
                {
                    <span class="typing-indicator" style="opacity: 0.6; font-style: italic;">Thinking...</span>
                }
            }
            else if (message.Role == "user")
            {
                @message.Text
            }
            else
            {
                <MarkdownView Content="@message.Text" />
            }

