args.ReplacementContent:
/* Right Pane (Reusable Multi-Purpose Sidecar) */
.pane-right {
  width: 0;
  min-width: 0;
  opacity: 0;
  border-left: none;
  background: var(--bg-panel);
  transition: width 0.22s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.15s ease;
  will-change: width, opacity;
}

.pane-right.open {
  width: 440px;
  min-width: 440px;
  opacity: 1;
  border-left: 1px solid var(--border-color);
}

.pane-right .pane-content {
  width: 440px;
  min-width: 440px;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Sidecar Navigation Tabs Header */
.sidecar-header-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px;
  background: var(--bg-panel-subtle);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.sidecar-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-muted);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.14s ease;
}

.sidecar-tab-btn:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.sidecar-tab-btn.active {
  color: var(--text-primary);
  background: var(--bg-active);
  font-weight: 600;
}

/* Artifact Inspector & Preview */
.artifact-viewer {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  gap: 10px;
}

.artifact-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
}

.artifact-code-pre {
  margin: 0;
  padding: 12px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  font-family: var(--font-mono, monospace);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-primary);
  overflow: auto;
  flex: 1;
  white-space: pre-wrap;
  word-break: break-word;
}

.artifact-live-preview {
  flex: 1;
  padding: 14px;
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: auto;
}

/* Git Diff Inspector Styles */
.diff-viewer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow-y: auto;
}

.diff-file-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-panel-subtle);
  overflow: hidden;
}

.diff-file-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border-color);
  font-size: 12px;
  font-weight: 600;
}

.diff-lines-container {
  display: flex;
  flex-direction: column;
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.4;
  overflow-x: auto;
}

.diff-line {
  display: flex;
  align-items: center;
  padding: 2px 8px;
  white-space: pre;
}

.diff-line.add {
  background: rgba(34, 197, 94, 0.12);
  color: #22c55e;
}

.diff-line.delete {
  background: rgba(239, 68, 68, 0.12);
  color: #ef4444;
}

.diff-line.header {
  background: var(--bg-hover);
  color: var(--text-muted);
  font-style: italic;
}

.diff-line-num {
  width: 32px;
  flex-shrink: 0;
  color: var(--text-muted);
  user-select: none;
  font-size: 10px;
}

.diff-line-content {
  flex: 1;
}

