.bottom-drawer {
  display: flex;
  flex-direction: column;
  background: var(--bg-panel);
  border-top: 1px solid var(--border-color);
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: max-height 0.22s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.15s ease;
  will-change: max-height, opacity;
}

.bottom-drawer.open {
  max-height: 220px;
  opacity: 1;
}

.bottom-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 14px;
  background: var(--bg-panel-subtle);
  border-bottom: 1px solid var(--border-color);
}

.bottom-drawer-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
}

.bottom-drawer-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.12s ease;
}

.bottom-drawer-tab:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.bottom-drawer-tab.active {
  color: var(--text-primary);
  background: var(--bg-active);
  font-weight: 600;
}

.bottom-drawer-body {
  padding: 10px 14px;
  overflow-y: auto;
  font-size: 12px;
  line-height: 1.45;
  flex: 1;
}

.drawer-status-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.drawer-status-card {
  padding: 8px 10px;
  background: var(--bg-panel-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.drawer-status-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.drawer-status-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

